@Test
default void listenerShouldReceiveWhenFailsLessThanMaxRetries() {
    EventCollector eventCollector = eventCollector();
    doThrow(new RuntimeException()).doThrow(new RuntimeException()).doCallRealMethod().when(eventCollector).event(EVENT);
    eventBus().register(eventCollector, GROUP_A);
    eventBus().dispatch(EVENT, NO_KEYS).block();
    getSpeedProfile().shortWaitCondition().untilAsserted(() -> assertThat(eventCollector.getEvents()).hasSize(1));
}

@Test
default void listenerShouldReceiveWhenFailsEqualsMaxRetries() {
    EventCollector eventCollector = eventCollector();
    //do throw  RetryBackoffConfiguration.DEFAULT.DEFAULT_MAX_RETRIES
    doThrow(new RuntimeException()).doThrow(new RuntimeException()).doThrow(new RuntimeException()).doCallRealMethod().when(eventCollector).event(EVENT);
    eventBus().register(eventCollector, GROUP_A);
    eventBus().dispatch(EVENT, NO_KEYS).block();
    getSpeedProfile().longWaitCondition().untilAsserted(() -> assertThat(eventCollector.getEvents()).hasSize(1));
}

@Test
default void listenerShouldNotReceiveWhenFailsGreaterThanMaxRetries() throws Exception {
    EventCollector eventCollector = eventCollector();
    //do throw  RetryBackoffConfiguration.DEFAULT.DEFAULT_MAX_RETRIES + 1 times
    doThrow(new RuntimeException()).doThrow(new RuntimeException()).doThrow(new RuntimeException()).doThrow(new RuntimeException()).doThrow(new RuntimeException()).doThrow(new RuntimeException()).doThrow(new RuntimeException()).doThrow(new RuntimeException()).doThrow(new RuntimeException()).doCallRealMethod().when(eventCollector).event(EVENT);
    eventBus().register(eventCollector, GROUP_A);
