@Test
default void retriesBackOffShouldDelayByExponentialGrowth() {
    ThrowingListener throwingListener = throwingListener();
    eventBus().register(throwingListener, GROUP_A);
    eventBus().dispatch(EVENT, NO_KEYS).block();
    getSpeedProfile().shortWaitCondition().untilAsserted(() -> assertThat(throwingListener.executionCount()).isEqualTo(4));
    SoftAssertions.assertSoftly(softly -> {
        List<Instant> timeElapsed = throwingListener.timeElapsed;
        softly.assertThat(timeElapsed).hasSize(RETRY_BACKOFF_CONFIGURATION.getMaxRetries() + 1);
        // first backOff
        long minFirstDelayAfter = DEFAULT_FIRST_BACKOFF.toMillis();
        // first_backOff * jitter factor (first_backOff * 0.5)
        long minSecondDelayAfter = DEFAULT_FIRST_BACKOFF.toMillis() / 2;
        // first_backOff * jitter factor (first_backOff * 1)
        long minThirdDelayAfter = DEFAULT_FIRST_BACKOFF.toMillis();
        softly.assertThat(timeElapsed.get(1)).isAfterOrEqualTo(timeElapsed.get(0).plusMillis(minFirstDelayAfter));
        softly.assertThat(timeElapsed.get(2)).isAfterOrEqualTo(timeElapsed.get(1).plusMillis(minSecondDelayAfter));
        softly.assertThat(timeElapsed.get(3)).isAfterOrEqualTo(timeElapsed.get(2).plusMillis(minThirdDelayAfter));
    });
}

