@Test
void generateDelayShouldReturnZeroWhenZeroRetryCount() {
    WaitDelayGenerator generator = WaitDelayGenerator.of(RetryBackoffConfiguration.DEFAULT);
    assertThat(generator.generateDelay(0)).isEqualTo(Duration.ofMillis(0));
}

@Test
void generateDelayShouldReturnByRandomInRangeOfExponentialGrowthOfRetryCount() {
    WaitDelayGenerator generator = WaitDelayGenerator.of(RetryBackoffConfiguration.builder().maxRetries(4).firstBackoff(Duration.ofMillis(100)).jitterFactor(0.5).build());
    SoftAssertions.assertSoftly(softly -> {
        softly.assertThat(generator.generateDelay(1).toMillis()).isBetween(50L, 150L);
        softly.assertThat(generator.generateDelay(2).toMillis()).isBetween(100L, 300L);
        softly.assertThat(generator.generateDelay(3).toMillis()).isBetween(200L, 600L);
        softly.assertThat(generator.generateDelay(4).toMillis()).isBetween(300L, 1200L);
    });
}

@Test
void generateDelayShouldReturnZeroWhenZeroMaxRetries() {
    WaitDelayGenerator generator = WaitDelayGenerator.of(RetryBackoffConfiguration.builder().maxRetries(0).firstBackoff(Duration.ofMillis(1000)).jitterFactor(0.5).build());
    SoftAssertions.assertSoftly(softly -> {
        softly.assertThat(generator.generateDelay(1)).isEqualTo(Duration.ZERO);
        softly.assertThat(generator.generateDelay(2)).isEqualTo(Duration.ZERO);
        softly.assertThat(generator.generateDelay(3)).isEqualTo(Duration.ZERO);
    });
}

@Test
void generateDelayShouldReturnZeroWhenZeroFirstBackOff() {
