    //do throw  RetryBackoffConfiguration.DEFAULT.DEFAULT_MAX_RETRIES + 1 times
    doThrow(new RuntimeException()).doThrow(new RuntimeException()).doThrow(new RuntimeException()).doThrow(new RuntimeException()).doThrow(new RuntimeException()).doThrow(new RuntimeException()).doThrow(new RuntimeException()).doThrow(new RuntimeException()).doThrow(new RuntimeException()).doCallRealMethod().when(listener).event(EVENT);
