    inVmEventDelivery.deliver(listener, EVENT, DeliveryOption.of(BackoffRetryer.of(RetryBackoffConfiguration.builder().maxRetries(8).firstBackoff(Duration.ofMillis(1)).jitterFactor(0.2).build(), listener), EventDelivery.PermanentFailureHandler.StoreToDeadLetters.of(GROUP_A, deadLetter))).block();
