@SuppressWarnings("unchecked")
void getMetaDataShouldReturnDefaultValueWhenNoReadRight() throws Exception {
    assumeTrue(mailboxManager.hasCapability(MailboxCapabilities.ACL));
    MailboxSession session1 = mailboxManager.createSystemSession(USER_1);
    MailboxSession session2 = mailboxManager.createSystemSession(USER_2);
    MailboxPath inbox1 = MailboxPath.inbox(session1);
    mailboxManager.createMailbox(inbox1, session1);
    mailboxManager.setRights(inbox1, MailboxACL.EMPTY.apply(MailboxACL.command().forUser(USER_2).rights(MailboxACL.Right.Lookup).asAddition()), session1);
    mailboxManager.getMailbox(inbox1, session1).appendMessage(AppendCommand.builder().recent().build(message), session1);
    MessageManager.MailboxMetaData metaData = mailboxManager.getMailbox(inbox1, session2).getMetaData(IGNORE, session2, MessageManager.MailboxMetaData.FetchGroup.UNSEEN_COUNT);
    assertSoftly(softly -> {
        softly.assertThat(metaData).extracting(MessageManager.MailboxMetaData::getHighestModSeq).isEqualTo(ModSeq.first());
        softly.assertThat(metaData).extracting(MessageManager.MailboxMetaData::getUidNext).isEqualTo(MessageUid.MIN_VALUE);
        softly.assertThat(metaData).extracting(MessageManager.MailboxMetaData::getMessageCount).isEqualTo(0L);
        softly.assertThat(metaData).extracting(MessageManager.MailboxMetaData::getUnseenCount).isEqualTo(0L);
        softly.assertThat(metaData).extracting(MessageManager.MailboxMetaData::getRecent).isEqualTo(ImmutableList.of());
