@Test
void expungeShouldBeExecutedAfterAllHooksFinish() throws Exception {
    CountDownLatch latchForHook1 = new CountDownLatch(1);
    when(preDeletionHook1.notifyDelete(any(PreDeletionHook.DeleteOperation.class))).thenAnswer(invocation -> {
        latchForHook1.countDown();
        return Mono.empty();
    });
    CountDownLatch latchForHook2 = new CountDownLatch(1);
    when(preDeletionHook2.notifyDelete(any(PreDeletionHook.DeleteOperation.class))).thenAnswer(invocation -> {
        latchForHook2.countDown();
        return Mono.empty();
    });
    ComposedMessageId composeId1 = inboxManager.appendMessage(AppendCommand.builder().build(message), session).getId();
    inboxManager.setFlags(new Flags(Flags.Flag.DELETED), MessageManager.FlagsUpdateMode.ADD, MessageRange.one(composeId1.getUid()), session);
    inboxManager.expunge(MessageRange.all(), session);
    latchForHook1.await();
    latchForHook2.await();
    assertThat(inboxManager.getMessages(MessageRange.one(composeId1.getUid()), FetchGroup.MINIMAL, session)).toIterable().isEmpty();
}

