@Test
default void highlightSearchShouldReturnHighLightedSubjectWhenMatched() throws Exception {
    MailboxSession session = session(USERNAME1);
    // Given m1,m2 with m1 has subject containing the searched word (Matthieu)
    ComposedMessageId m1 = appendMessage(MessageManager.AppendCommand.from(Message.Builder.of().setTo("to@james.local").setSubject("Hallo, Thx Matthieu for your help").setBody("append contentA to inbox", StandardCharsets.UTF_8)), session).getId();
    ComposedMessageId m2 = appendMessage(MessageManager.AppendCommand.from(Message.Builder.of().setTo("to@james.local").setSubject("Hallo, Thx Alex for your help").setBody("append contentB to inbox", StandardCharsets.UTF_8)), session).getId();
    verifyMessageWasIndexed(2);
    // When searching for the word (Matthieu) in the subject
    MultimailboxesSearchQuery multiMailboxSearch = MultimailboxesSearchQuery.from(SearchQuery.of(SearchQuery.subject("Matthieu"))).inMailboxes(List.of(m2.getMailboxId())).build();
    List<SearchSnippet> searchSnippets = Flux.from(testee().highlightSearch(List.of(m1.getMessageId(), m2.getMessageId()), multiMailboxSearch, session)).collectList().block();
    // Then highlightSearch should return the SearchSnippet with the highlightedSubject containing the word (Matthieu)
    assertThat(searchSnippets).hasSize(1);
    assertSoftly(softly -> {
        softly.assertThat(searchSnippets.getFirst().messageId()).isEqualTo(m1.getMessageId());
        softly.assertThat(searchSnippets.getFirst().highlightedSubject()).contains("Hallo, Thx <mark>Matthieu</mark> for your help");
    });
}

