        zipAssert.containsExactlyEntriesMatching(//MAILBOX 1 with its annotations
        hasName(MAILBOX_1.getName() + "/"), hasName(MAILBOX_1.getName() + "/annotations/").isDirectory(), hasName(MAILBOX_1.getName() + "/annotations/" + ANNOTATION_1.getKey().asString()).hasStringContent(ANNOTATION_1_CONTENT), //MAILBOX 2 with its annotations
