@Test
void shouldNotLoadMoreDataThanPrefetch() throws Exception {
    MailboxSession session = mailboxManager.createSystemSession(USER_1);
    MailboxPath inbox = MailboxPath.inbox(session);
    mailboxManager.createMailbox(inbox, session).get();
    MessageManager inboxManager = mailboxManager.getMailbox(inbox, session);
    MessageManager.AppendCommand appendCommand = MessageManager.AppendCommand.from(Message.Builder.of().setSubject("Test").setBody("01234567890\r\n", StandardCharsets.UTF_8));
    IntStream.range(0, 64).forEach(Throwing.intConsumer(i -> inboxManager.appendMessage(appendCommand, session)));
    cassandra.getCassandraCluster().getConf().printStatements();
    StatementRecorder statementRecorder = cassandra.getCassandraCluster().getConf().recordStatements();
    Flux.from(inboxManager.getMessagesReactive(MessageRange.all(), FetchGroup.FULL_CONTENT, session)).skip(10).next().block();
    Thread.sleep(1000);
    assertThat(statementRecorder.listExecutedStatements(StatementRecorder.Selector.preparedStatement("SELECT * FROM blobs WHERE id=:id"))).hasSizeLessThanOrEqualTo(// times 2 for header and blob, 10 skipped 5 prefetch.
    30);
    cassandra.getCassandraCluster().getConf().stopPrintingStatements();
}

