@Disabled("Expected concurrency issue in the absence of performance expensive LightWeight transaction" + "As the Uid validity is updated only when equal to 0 (1 chance out of 4 billion) the benefits of LWT don't" + "outweigh the costs")
@Test
void retrieveMailboxShouldNotBeSubjectToDataRaceUponUidValiditySanitizing(CassandraCluster cassandra) throws Exception {
    testee.save(mailbox1).block();
    // Hack to insert a faulty value
    cassandra.getConf().execute(update("mailbox").setColumn("uidvalidity", literal(-12)).where(column("id").isEqualTo(literal(CASSANDRA_ID_1.asUuid()))).build());
    Barrier barrier = new Barrier(2);
    cassandra.getConf().registerScenario(awaitOn(barrier).thenExecuteNormally().times(2).whenQueryStartsWith("UPDATE mailbox SET"));
    CompletableFuture<Mailbox> readMailbox1 = testee.retrieveMailbox(CASSANDRA_ID_1).toFuture();
    CompletableFuture<Mailbox> readMailbox2 = testee.retrieveMailbox(CASSANDRA_ID_1).toFuture();
    barrier.awaitCaller();
    barrier.releaseCaller();
    assertThat(readMailbox1.get().getUidValidity()).isEqualTo(readMailbox2.get().getUidValidity());
}

