@Test
void renameWithUpdateShouldBeThreadSafe() throws Exception {
    Mailbox mailbox = testee.create(MAILBOX_PATH, UID_VALIDITY).block();
    mailbox.setName("newName");
    ConcurrentTestRunner.builder().operation((a, b) -> testee.rename(mailbox).block()).threadCount(THREAD_COUNT).operationCount(OPERATION_COUNT).runAcceptingErrorsWithin(Duration.ofMinutes(1));
