@Test
void deleteShouldDeleteWhenRowExists() {
    CassandraMessageId messageId = CassandraMessageId.Factory.of(Uuids.timeBased());
    CassandraId mailboxId = CassandraId.timeBased();
    MessageUid messageUid = MessageUid.of(1);
    testee.insert(CassandraMessageMetadata.builder().ids(ComposedMessageIdWithMetaData.builder().composedMessageId(new ComposedMessageId(mailboxId, messageId, messageUid)).flags(new Flags()).modSeq(ModSeq.of(1)).threadId(ThreadId.fromBaseMessageId(messageId)).build()).internalDate(new Date()).bodyStartOctet(18L).size(36L).headerContent(Optional.of(HEADER_BLOB_ID_1)).build()).block();
