@Test
void retrieveMessageShouldHandlePossibleNullInternalDate() {
    CassandraMessageId messageId = CassandraMessageId.Factory.of(Uuids.timeBased());
    CassandraId mailboxId = CassandraId.timeBased();
    MessageUid messageUid = MessageUid.of(1);
    ComposedMessageIdWithMetaData expectedComposedMessageId = ComposedMessageIdWithMetaData.builder().composedMessageId(new ComposedMessageId(mailboxId, messageId, messageUid)).flags(new Flags()).modSeq(ModSeq.of(1)).threadId(ThreadId.fromBaseMessageId(messageId)).build();
    testee.insertNullInternalDateAndHeaderContent(CassandraMessageMetadata.builder().ids(expectedComposedMessageId).build()).block();
