@Test
void failedInsertsShouldBeRetried(CassandraCluster cassandra) throws Exception {
    Barrier insertBarrier = new Barrier(2);
    Barrier retryBarrier = new Barrier(1);
    cassandra.getConf().registerScenario(executeNormally().times(2).whenQueryStartsWith("SELECT nextmodseq FROM modseq WHERE mailboxid=:mailboxid"), awaitOn(insertBarrier).thenExecuteNormally().times(2).whenQueryStartsWith("INSERT INTO modseq (nextmodseq,mailboxid)"), awaitOn(retryBarrier).thenExecuteNormally().times(1).whenQueryStartsWith("SELECT nextmodseq FROM modseq WHERE mailboxid=:mailboxid"));
    CompletableFuture<ModSeq> operation1 = modSeqProvider.nextModSeqReactive(CASSANDRA_ID).subscribeOn(Schedulers.boundedElastic()).toFuture();
    CompletableFuture<ModSeq> operation2 = modSeqProvider.nextModSeqReactive(CASSANDRA_ID).subscribeOn(Schedulers.boundedElastic()).toFuture();
    insertBarrier.awaitCaller();
    insertBarrier.releaseCaller();
    retryBarrier.awaitCaller();
    retryBarrier.releaseCaller();
    // Artificially fail the insert failure
    cassandra.getConf().execute(deleteFrom(TABLE_NAME).where(column(MAILBOX_ID).isEqualTo(literal(CASSANDRA_ID.asUuid()))).build());
    retryBarrier.releaseCaller();
    assertThatCode(() -> operation1.get(1, TimeUnit.SECONDS)).doesNotThrowAnyException();
    assertThatCode(() -> operation2.get(1, TimeUnit.SECONDS)).doesNotThrowAnyException();
}

