        softly.assertThat(modseq3).isEqualTo(ModSeq.of(13));
        softly.assertThat(modseq4).isEqualTo(ModSeq.of(13));
        softly.assertThat(modseq5).isEqualTo(ModSeq.of(13));
        softly.assertThat(modseq6).isEqualTo(ModSeq.of(13));
    });
}

