@Test
void fixMessageInconsistenciesShouldFixInconsistency() {
    // Given inconsistent data
    mailboxDAO.save(MAILBOX).block();
    messageIdDAO.insert(CassandraMessageMetadata.builder().ids(ComposedMessageIdWithMetaData.builder().composedMessageId(new ComposedMessageId(CASSANDRA_ID_1, MESSAGE_ID_1, MESSAGE_UID_1)).flags(new Flags(Flags.Flag.DELETED)).modSeq(ModSeq.of(1)).threadId(ThreadId.fromBaseMessageId(MESSAGE_ID_1)).build()).internalDate(new Date()).bodyStartOctet(18L).headerContent(Optional.of(HEADER_BLOB_ID_1)).size(36L).build()).block();
    deletedMessageDAO.addDeleted(CASSANDRA_ID_1, MESSAGE_UID_2).block();
    // When fixing inconsistencies
    assertThat(testee.fixInconsistencies(new Context(), TargetFlag.DELETED).block()).isEqualTo(Task.Result.COMPLETED);
    // Then the inconsistency should be fixed
    // CASSANDRA_ID_1 - MESSAGE_UID_2 should be removed
    // CASSANDRA_ID_1 - MESSAGE_UID_1 should be added
    assertThat(deletedMessageDAO.retrieveDeletedMessage(CASSANDRA_ID_1, MessageRange.all()).collectList().block()).contains(MESSAGE_UID_1);
}

@Test
void fixInconsistenciesShouldWorkOnSeveralMailbox() {
    mailboxDAO.save(MAILBOX).block();
    mailboxDAO.save(MAILBOX_2).block();
    messageIdDAO.insert(CassandraMessageMetadata.builder().ids(ComposedMessageIdWithMetaData.builder().composedMessageId(new ComposedMessageId(CASSANDRA_ID_1, MESSAGE_ID_1, MESSAGE_UID_1)).flags(new Flags(Flags.Flag.DELETED)).modSeq(ModSeq.of(1)).threadId(ThreadId.fromBaseMessageId(MESSAGE_ID_1)).build()).internalDate(new Date()).bodyStartOctet(18L).headerContent(Optional.of(HEADER_BLOB_ID_1)).size(36L).build()).block();
    messageIdDAO.insert(CassandraMessageMetadata.builder().ids(ComposedMessageIdWithMetaData.builder().composedMessageId(new ComposedMessageId(CASSANDRA_ID_2, MESSAGE_ID_2, MESSAGE_UID_2)).flags(new Flags(Flags.Flag.DELETED)).modSeq(ModSeq.of(1)).threadId(ThreadId.fromBaseMessageId(MESSAGE_ID_2)).build()).internalDate(new Date()).bodyStartOctet(18L).headerContent(Optional.of(HEADER_BLOB_ID_1)).size(36L).build()).block();
    MessageUid messageUid3 = MessageUid.of(3);
    deletedMessageDAO.addDeleted(CASSANDRA_ID_1, messageUid3).block();
    deletedMessageDAO.addDeleted(CASSANDRA_ID_2, MESSAGE_UID_2).block();
    // When fixing inconsistencies
    assertThat(testee.fixInconsistencies(new Context(), TargetFlag.DELETED).block()).isEqualTo(Task.Result.COMPLETED);
    // Then the inconsistency should be fixed
    // CASSANDRA_ID_1 - messageUid3 should be removed
    // CASSANDRA_ID_1 - messageUid1 should be added
    // CASSANDRA_ID_2 - messageUid2 should be kept
    assertThat(deletedMessageDAO.retrieveDeletedMessage(CASSANDRA_ID_1, MessageRange.all()).collectList().block()).contains(MESSAGE_UID_1);
    assertThat(deletedMessageDAO.retrieveDeletedMessage(CASSANDRA_ID_2, MessageRange.all()).collectList().block()).contains(MESSAGE_UID_2);
}

