    Iterator<MailboxMessage> retrievedMessageIterator = messageMapper.findInMailbox(attachmentsMailbox, MessageRange.one(messageWith2Attachments.getUid()), fetchType, LIMIT);
    AttachmentMetadata attachment1 = messageWith2Attachments.getAttachments().get(0).getAttachment();
    AttachmentMetadata attachment2 = messageWith2Attachments.getAttachments().get(1).getAttachment();
    MessageAttachmentMetadata attachmentMetadata1 = messageWith2Attachments.getAttachments().get(0);
    MessageAttachmentMetadata attachmentMetadata2 = messageWith2Attachments.getAttachments().get(1);
    List<MessageAttachmentMetadata> messageAttachments = retrievedMessageIterator.next().getAttachments();
    // JPA does not support MessageId
    assertThat(messageAttachments).extracting(MessageAttachmentMetadata::getAttachment).extracting("attachmentId", "size", "type").containsExactlyInAnyOrder(tuple(attachment1.getAttachmentId(), attachment1.getSize(), attachment1.getType()), tuple(attachment2.getAttachmentId(), attachment2.getSize(), attachment2.getType()));
    assertThat(messageAttachments).extracting(MessageAttachmentMetadata::getAttachmentId, MessageAttachmentMetadata::getName, MessageAttachmentMetadata::getCid, MessageAttachmentMetadata::isInline).containsExactlyInAnyOrder(tuple(attachmentMetadata1.getAttachmentId(), attachmentMetadata1.getName(), attachmentMetadata1.getCid(), attachmentMetadata1.isInline()), tuple(attachmentMetadata2.getAttachmentId(), attachmentMetadata2.getName(), attachmentMetadata2.getCid(), attachmentMetadata2.isInline()));
}

