void addAOutdatedMessageInOutBoxShouldNotIndex() throws Exception {
    // given
    MailboxPath outboxPath = MailboxPath.forUser(USERNAME, DefaultMailboxes.OUTBOX);
    Mailbox outbox = mapperFactory.getMailboxMapper(session).create(outboxPath, UidValidity.generate()).block();
    assert outbox != null;
    Mailbox inbox = mailbox;
    SimpleMailboxMessage outDatedMessage = SimpleMailboxMessage.builder().mailboxId(inbox.getMailboxId()).flags(new Flags()).bodyStartOctet(BODY_START_OCTET).internalDate(new Date(1433628000000L)).size(SIZE).content(new ByteContent("message".getBytes(StandardCharsets.UTF_8))).properties(new PropertyBuilder()).modseq(MOD_SEQ).messageId(MESSAGE_ID_1).threadId(ThreadId.fromBaseMessageId(MESSAGE_ID_1)).uid(MESSAGE_UID_1).build();
    mapperFactory.getMessageMapper(session).add(inbox, outDatedMessage);
    // when
    MessageMetaData outdatedMessageMetaData = new MessageMetaData(MESSAGE_UID_1, outDatedMessage.getModSeq(), outDatedMessage.metaData().getFlags(), SIZE, outDatedMessage.getInternalDate(), outDatedMessage.getSaveDate(), MESSAGE_ID_1, outDatedMessage.getThreadId());
    MailboxEvents.Added addedOutDatedEvent = new MailboxEvents.Added(MailboxSession.SessionId.of(42), BOB, outboxPath, outbox.getMailboxId(), ImmutableSortedMap.of(MESSAGE_UID_1, outdatedMessageMetaData), Event.EventId.random(), !IS_DELIVERY, IS_APPENDED, Optional.empty());
    Mono.from(testee.reactiveEvent(addedOutDatedEvent)).block();
    // then
    Thread.sleep(1000);
    assertThat(testee.search(session, outbox, SearchQuery.of(SearchQuery.all())).collectList().block()).isEmpty();
}

