@Test
void searchingInALargeNumberOfMailboxesShouldReturnAllMailboxesMessagesUid() {
    MailboxSession session = MailboxSessionUtil.create(USERNAME);
    int numberOfMailboxes = 700;
    List<MailboxPath> mailboxPaths = IntStream.range(0, numberOfMailboxes).mapToObj(index -> MailboxPath.forUser(USERNAME, "mailbox" + index)).collect(ImmutableList.toImmutableList());
    List<MailboxId> mailboxIds = Flux.fromIterable(mailboxPaths).flatMap(mailboxPath -> storeMailboxManager.createMailboxReactive(mailboxPath, session), 16).collectList().block();
    List<ComposedMessageId> composedMessageIds = Flux.fromIterable(mailboxPaths).flatMap(Throwing.function(mailboxPath -> addMessage(session, mailboxPath)), 16).collectList().block();
    awaitForOpenSearch(QueryBuilders.matchAll().build().toQuery(), composedMessageIds.size());
    MultimailboxesSearchQuery multimailboxesSearchQuery = MultimailboxesSearchQuery.from(SearchQuery.of(SearchQuery.all())).inMailboxes(mailboxIds).build();
    List<MessageId> expectedMessageIds = composedMessageIds.stream().map(ComposedMessageId::getMessageId).collect(ImmutableList.toImmutableList());
    assertThat(storeMailboxManager.search(multimailboxesSearchQuery, session, numberOfMailboxes + 1).collectList().block()).containsExactlyInAnyOrderElementsOf(expectedMessageIds);
}

