@Test
void shouldDeserializeNestedStructure() throws Exception {
    String queryJson = "{  " + "  \"combinator\": \"and\",  " + "  \"criteria\": [  " + "    {  " + "      \"combinator\": \"and\",  " + "      \"criteria\": [  " + "        {\"fieldName\": \"subject\", \"operator\": \"contains\", \"value\": \"" + SUBJECT + "\"}," + "        {\"fieldName\": \"sender\", \"operator\": \"equals\", \"value\": \"" + SENDER.asString() + "\"}" + "      ]  " + "    },  " + "    {\"fieldName\": \"hasAttachment\", \"operator\": \"equals\", \"value\": \"true\"}" + "  ]  " + "}  ";
    QueryDTO queryDTO = objectMapper.readValue(queryJson, QueryDTO.class);
    assertThat(queryDTO).isEqualTo(QueryDTO.and(QueryDTO.and(CriterionDTO.from(FieldName.SUBJECT, Operator.CONTAINS, SUBJECT), CriterionDTO.from(FieldName.SENDER, Operator.EQUALS, SENDER.asString())), CriterionDTO.from(FieldName.HAS_ATTACHMENT, Operator.EQUALS, "true")));
}

