@Test
public void fromShouldReadXMLConfigurationWhenRenderingInformationPartiallyOmited() throws Exception {
    XMLConfiguration xmlConfiguration = FileConfigurationProvider.getConfig(toStream("<configuration>
" + "  <thresholds>
" + "    <threshold>" + "      <value>0.85</value>" + "      <bodyTemplate>" + BODY_TEMPLATE + "</bodyTemplate>
" + "    </threshold>
" + "    <threshold>
" + "      <value>0.98</value>
" + "      <subjectTemplate>" + OTHER_SUBJECT_TEMPLATE + "</subjectTemplate>
" + "    </threshold>
" + "    <threshold>
" + "      <value>0.99</value>
" + "    </threshold>
" + "  </thresholds>
" + "  <gracePeriod>3 days</gracePeriod>
" + "  <name>listener-name</name>
" + "</configuration>"));
    QuotaMailingListenerConfiguration result = QuotaMailingListenerConfiguration.from(xmlConfiguration);
    assertThat(result).isEqualTo(QuotaMailingListenerConfiguration.builder().addThreshold(new QuotaThreshold(0.85), RenderingInformation.from(Optional.of(BODY_TEMPLATE), Optional.empty())).addThreshold(new QuotaThreshold(0.98), RenderingInformation.from(Optional.empty(), Optional.of(OTHER_SUBJECT_TEMPLATE))).addThreshold(new QuotaThreshold(0.99), RenderingInformation.from(Optional.empty(), Optional.empty())).gracePeriod(Duration.ofDays(3)).name("listener-name").build());
}

