@Test
void renderingShouldUsePerThresholdTemplate() throws Exception {
    QuotaMailingListenerConfiguration configuration = QuotaMailingListenerConfiguration.builder().addThreshold(_80, RenderingInformation.from("classpath://templates/body1.mustache", "classpath://templates/subject1.mustache")).addThreshold(_95, RenderingInformation.from("classpath://templates/body2.mustache", "classpath://templates/subject2.mustache")).build();
    QuotaThresholdNotice quotaThresholdNotice1 = QuotaThresholdNotice.builder().withConfiguration(configuration).sizeQuota(Sizes._82_PERCENT).countQuota(Counts._UNLIMITED).countThreshold(HistoryEvolution.higherThresholdReached(new QuotaThresholdChange(_80, NOW), NotAlreadyReachedDuringGracePeriod)).build().get();
    QuotaThresholdNotice quotaThresholdNotice2 = QuotaThresholdNotice.builder().withConfiguration(configuration).sizeQuota(Sizes._992_PERTHOUSAND).countQuota(Counts._UNLIMITED).countThreshold(HistoryEvolution.higherThresholdReached(new QuotaThresholdChange(_95, NOW), NotAlreadyReachedDuringGracePeriod)).build().get();
    SoftAssertions softly = new SoftAssertions();
    softly.assertThat(quotaThresholdNotice1.generateSubject(fileSystem)).isEqualTo("[SUBJECT_1]");
    softly.assertThat(quotaThresholdNotice1.generateReport(fileSystem)).isEqualTo("[BODY_1]");
    softly.assertThat(quotaThresholdNotice2.generateSubject(fileSystem)).isEqualTo("[SUBJECT_2]");
    softly.assertThat(quotaThresholdNotice2.generateReport(fileSystem)).isEqualTo("[BODY_2]");
    softly.assertAll();
}

