    FlagsUpdateCalculator flagsUpdateCalculator = new FlagsUpdateCalculator(new FlagsBuilder().add(Flags.Flag.DELETED, Flags.Flag.FLAGGED).add("userflag").build(), MessageManager.FlagsUpdateMode.ADD);
