@Test
protected void updateAclShouldWorkWellInMultiThreadEnv() throws ExecutionException, InterruptedException {
    MailboxACL.Rfc4314Rights rights = new MailboxACL.Rfc4314Rights(MailboxACL.Right.Administer, MailboxACL.Right.Write);
    MailboxACL.Rfc4314Rights newRights = new MailboxACL.Rfc4314Rights(MailboxACL.Right.Write);
    ConcurrentTestRunner.builder().reactorOperation((threadNumber, step) -> {
        int userNumber = threadNumber / 2;
        MailboxACL.EntryKey key = MailboxACL.EntryKey.createUserEntryKey("user" + userNumber);
        if (threadNumber % 2 == 0) {
            return mailboxMapper.updateACL(benwaInboxMailbox, MailboxACL.command().key(key).rights(rights).asReplacement()).then();
        } else {
            return mailboxMapper.updateACL(benwaInboxMailbox, MailboxACL.command().key(key).rights(newRights).asAddition()).then();
        }
    }).threadCount(10).operationCount(1).runSuccessfullyWithin(Duration.ofMinutes(1));
    MailboxACL expectedMailboxACL = new MailboxACL(IntStream.range(0, 5).boxed().collect(ImmutableMap.toImmutableMap(userNumber -> MailboxACL.EntryKey.createUserEntryKey("user" + userNumber), userNumber -> rights)));
    assertThat(mailboxMapper.findMailboxById(benwaInboxMailbox.getMailboxId()).block().getACL()).isEqualTo(expectedMailboxACL);
}

