@Test
public void setFlagsShouldWorkWithConcurrencyWithAdd() throws Exception {
    Assume.assumeTrue(mapperProvider.getSupportedCapabilities().contains(MapperProvider.Capabilities.THREAD_SAFE_FLAGS_UPDATE));
    message1.setUid(mapperProvider.generateMessageUid(benwaInboxMailbox));
    message1.setModSeq(mapperProvider.generateModSeq(benwaInboxMailbox));
    sut.save(message1);
    int threadCount = 2;
    int updateCount = 10;
    ConcurrentTestRunner.builder().operation((threadNumber, step) -> sut.setFlags(message1.getMessageId(), ImmutableList.of(message1.getMailboxId()), new Flags("custom-" + threadNumber + "-" + step), FlagsUpdateMode.ADD).block()).threadCount(threadCount).operationCount(updateCount).runSuccessfullyWithin(Duration.ofMinutes(1));
    List<MailboxMessage> messages = sut.find(ImmutableList.of(message1.getMessageId()), FetchType.FULL);
    assertThat(messages).hasSize(1);
    assertThat(messages.get(0).createFlags().getUserFlags()).hasSize(threadCount * updateCount);
}

@Test
public void setFlagsShouldWorkWithConcurrencyWithRemove() throws Exception {
    Assume.assumeTrue(mapperProvider.getSupportedCapabilities().contains(MapperProvider.Capabilities.THREAD_SAFE_FLAGS_UPDATE));
    message1.setUid(mapperProvider.generateMessageUid(benwaInboxMailbox));
    message1.setModSeq(mapperProvider.generateModSeq(benwaInboxMailbox));
    sut.save(message1);
    int threadCount = 4;
    int updateCount = 20;
    ConcurrentTestRunner.builder().operation((threadNumber, step) -> {
        if (step < updateCount / 2) {
            sut.setFlags(message1.getMessageId(), ImmutableList.of(message1.getMailboxId()), new Flags("custom-" + threadNumber + "-" + step), FlagsUpdateMode.ADD).block();
        } else {
            sut.setFlags(message1.getMessageId(), ImmutableList.of(message1.getMailboxId()), new Flags("custom-" + threadNumber + "-" + (updateCount - step - 1)), FlagsUpdateMode.REMOVE).block();
        }
    }).threadCount(threadCount).operationCount(updateCount).runSuccessfullyWithin(Duration.ofMinutes(1));
    List<MailboxMessage> messages = sut.find(ImmutableList.of(message1.getMessageId()), FetchType.FULL);
    assertThat(messages).hasSize(1);
    assertThat(messages.get(0).createFlags().getUserFlags()).isEmpty();
}

