@Test
public void userFlagsUpdateShouldWorkInConcurrentEnvironment() throws Exception {
    Assume.assumeTrue(mapperProvider.getSupportedCapabilities().contains(MapperProvider.Capabilities.THREAD_SAFE_FLAGS_UPDATE));
    saveMessages();
    int threadCount = 8;
    int updateCount = 40;
    ConcurrentTestRunner.builder().operation((threadNumber, step) -> messageMapper.updateFlags(benwaInboxMailbox, message1.getUid(), new FlagsUpdateCalculator(new Flags("custom-" + threadNumber + "-" + step), FlagsUpdateMode.ADD))).threadCount(threadCount).operationCount(updateCount).runSuccessfullyWithin(Duration.ofMinutes(1));
    Iterator<MailboxMessage> messages = messageMapper.findInMailbox(benwaInboxMailbox, MessageRange.one(message1.getUid()), FetchType.METADATA, 1);
    assertThat(messages.hasNext()).isTrue();
    assertThat(messages.next().createFlags().getUserFlags()).hasSize(threadCount * updateCount);
}

@Test
public void setFlagsShouldWorkWithConcurrencyWithRemove() throws Exception {
    Assume.assumeTrue(mapperProvider.getSupportedCapabilities().contains(MapperProvider.Capabilities.THREAD_SAFE_FLAGS_UPDATE));
    saveMessages();
    int threadCount = 8;
    int updateCount = 40;
    ConcurrentTestRunner.builder().operation((threadNumber, step) -> {
        if (step < updateCount / 2) {
            messageMapper.updateFlags(benwaInboxMailbox, message1.getUid(), new FlagsUpdateCalculator(new Flags("custom-" + threadNumber + "-" + step), FlagsUpdateMode.ADD));
        } else {
            messageMapper.updateFlags(benwaInboxMailbox, message1.getUid(), new FlagsUpdateCalculator(new Flags("custom-" + threadNumber + "-" + (updateCount - step - 1)), FlagsUpdateMode.REMOVE));
        }
    }).threadCount(threadCount).operationCount(updateCount).runSuccessfullyWithin(Duration.ofMinutes(1));
    Iterator<MailboxMessage> messages = messageMapper.findInMailbox(benwaInboxMailbox, MessageRange.one(message1.getUid()), FetchType.METADATA, 1);
    assertThat(messages.hasNext()).isTrue();
    assertThat(messages.next().createFlags().getUserFlags()).isEmpty();
}

