").getHeader();
    assertThat(MimeMessageHeadersUtil.parseInReplyTo(header)).contains(new MimeMessageId("<CANKoxfUNSvbjBuUaQSQiFavvDH-OvVig772-dKMrAbsisoZa1A@mail.gmail.com>"));
}

