@Test
void validTextCalendarShouldNotBeSanitized() throws Exception {
    FakeMail mail = FakeMail.builder().name("mail").mimeMessage(MimeMessageBuilder.mimeMessageBuilder().setMultipartWithBodyParts(MimeMessageBuilder.bodyPartBuilder().type("text/calendar").data("Not empty").addHeader("X-CUSTOM", "Because it is a valid ICS it should not be pushed in body"))).build();
    testee.service(mail);
    Object content = mail.getMessage().getContent();
    assertThat(content).isInstanceOf(Multipart.class);
    Multipart multipart = (Multipart) content;
    assertThat(multipart.getCount()).isEqualTo(1);
    SharedByteArrayInputStream inputStream = (SharedByteArrayInputStream) multipart.getBodyPart(0).getContent();
    assertThat(IOUtils.toString(inputStream, StandardCharsets.UTF_8)).doesNotContain("X-CUSTOM");
}

@Test
void buildShouldWork() throws Exception {
    byte[] ics = ClassLoaderUtils.getSystemResourceAsByteArray("ics/meeting.ics");
    Calendar calendar = new CalendarBuilder().build(new ByteArrayInputStream(ics));
    MailAddress recipient = MailAddressFixture.ANY_AT_JAMES;
    MailAddress sender = MailAddressFixture.OTHER_AT_JAMES;
    ICALAttributeDTO ical = ICALAttributeDTO.builder().from(calendar, ics).sender(sender).recipient(recipient).replyTo(sender);
    SoftAssertions.assertSoftly(Throwing.consumer(softly -> {
        softly.assertThat(ical.getRecipient()).isEqualTo(recipient.asString());
        softly.assertThat(ical.getSender()).isEqualTo(sender.asString());
        softly.assertThat(ical.getUid()).contains("f1514f44bf39311568d640727cff54e819573448d09d2e5677987ff29caa01a9e047feb2aab16e43439a608f28671ab7" + "c10e754ce92be513f8e04ae9ff15e65a9819cf285a6962bc");
        softly.assertThat(ical.getMethod()).contains("REQUEST");
        softly.assertThat(ical.getRecurrenceId()).isEmpty();
        softly.assertThat(ical.getDtstamp()).contains("20170106T115036Z");
        softly.assertThat(ical.getSequence()).isEqualTo("0");
        softly.assertThat(ical.getIcal()).isEqualTo(new String(ics, "UTF-8"));
    }));
}

