    ExtensionField extensionField2 = ExtensionField.builder().fieldName("name2").rawValue("value2").build();
    Gateway gateway = Gateway.builder().name(Text.fromRawText("address")).build();
    OriginalMessageId originalMessageIdField = new OriginalMessageId("msgId");
    OriginalRecipient originalRecipientField = OriginalRecipient.builder().originalRecipient(Text.fromRawText("originalRecipient")).build();
    ReportingUserAgent reportingUserAgentField = ReportingUserAgent.builder().userAgentName("name").build();
    Error errorField1 = new Error(Text.fromRawText("error 1"));
    Error errorField2 = new Error(Text.fromRawText("error 2"));
    MDNReport mdnReport = MDNReport.builder().withExtensionField(extensionField1).withExtensionField(extensionField2).finalRecipientField(finalRecipientField).dispositionField(disposition).gatewayField(gateway).originalMessageIdField(originalMessageIdField).originalRecipientField(originalRecipientField).reportingUserAgentField(reportingUserAgentField).addErrorField(errorField1).addErrorField(errorField2).build();
    assertThat(mdnReport).isEqualTo(new MDNReport(Optional.of(reportingUserAgentField), Optional.of(gateway), Optional.of(originalRecipientField), finalRecipientField, Optional.of(originalMessageIdField), disposition, ImmutableList.of(errorField1, errorField2), ImmutableList.of(extensionField1, extensionField2)));
}

