    Thread.sleep(ONE_SECOND.toMillis());
    timeMetric1.stopAndPublish();
    TimeMetric timeMetric2 = testee.timer(TIME_METRIC_NAME);
    Thread.sleep(FIVE_SECONDS.toMillis());
    timeMetric2.stopAndPublish();
    assertThat(testee.executionTimesFor(TIME_METRIC_NAME)).hasSize(2);
    assertThat(testee.executionTimesFor(TIME_METRIC_NAME)).element(0).satisfies(duration -> assertThat(duration).isGreaterThanOrEqualTo(ONE_SECOND));
