    UidRange[] range = { new UidRange(MessageUid.of(2)), new UidRange(MessageUid.of(4)), new UidRange(MessageUid.of(9)), new UidRange(MessageUid.of(16)), new UidRange(MessageUid.of(25)), new UidRange(MessageUid.of(36)), new UidRange(MessageUid.of(49)), new UidRange(MessageUid.of(64)), new UidRange(MessageUid.of(81)), new UidRange(MessageUid.of(100)) };
    checkUid("2,4,9,16,25,36,49,64,81,100", UidRange.mergeRanges(Arrays.asList(range)).toArray(UidRange[]::new));
}

@Test
void testEndStarUids() throws Exception {
    UidRange[] range = { new UidRange(MessageUid.of(8)), new UidRange(MessageUid.of(10), MessageUid.of(11)), new UidRange(MessageUid.of(17)), new UidRange(MessageUid.of(100), MessageUid.MAX_VALUE) };
