default void noCallToBlobStoreWhenMoveMessages(GuiceJamesServer server) throws Exception {
    // Given Mailbox1, Mailbox2. And a message in Mailbox1
    String myBox1 = "MyBox1" + UUID.randomUUID();
    String myBox2 = "MyBox2" + UUID.randomUUID();
    MailboxProbeImpl mailboxProbe = server.getProbe(MailboxProbeImpl.class);
    mailboxProbe.createMailbox("#private", JAMES_USER_1, myBox1);
    mailboxProbe.createMailbox("#private", JAMES_USER_1, myBox2);
    ComposedMessageId composedMessageId = server.getProbe(MailboxProbeImpl.class).appendMessage(JAMES_USER_1, MailboxPath.forUser(Username.of(JAMES_USER_1), myBox1), MessageManager.AppendCommand.from(Message.Builder.of().setSubject("test").setBody("testmail", StandardCharsets.UTF_8).build()));
    try (TestIMAPClient imapClient = new TestIMAPClient()) {
        int imapPort = server.getProbe(ImapGuiceProbe.class).getImapPort();
        imapClient.connect("127.0.0.1", imapPort).login(JAMES_USER_1, PASSWORD_1).select(myBox1).awaitMessageCount(CALMLY_AWAIT, 1);
        StatementRecorder statementRecorder = server.getProbe(TestingSessionProbe.class).getTestingSession().recordStatements();
        // When move MyBox1 -> MyBox2
        imapClient.moveFirstMessage(myBox2);
        imapClient.awaitMessageCount(CALMLY_AWAIT, 0);
        imapClient.select(myBox2).awaitMessageCount(CALMLY_AWAIT, 1);
        // Then no call to blob store
        assertSoftly(softly -> {
            softly.assertThat(statementRecorder.listExecutedStatements(StatementRecorder.Selector.preparedStatementStartingWith("SELECT * FROM blobpartsinbucket WHERE"))).hasSize(0);
            softly.assertThat(statementRecorder.listExecutedStatements(StatementRecorder.Selector.preparedStatementStartingWith("SELECT * FROM blobparts WHERE"))).hasSize(0);
        });
    }
}

