@Test
void readBytesShouldRecordDistinctTimingsWhenRepeatAndBackendRead() {
    BlobId blobId = Mono.from(testee.save(DEFAULT_BUCKETNAME, ELEVEN_KILOBYTES, SIZE_BASED)).block();
    Duration delay = Duration.ofMillis(1000);
    Mono.from(testee.readBytes(DEFAULT_BUCKETNAME, blobId, HIGH_PERFORMANCE)).then(Mono.delay(delay)).repeat(2).blockLast();
    assertThat(metricFactory.executionTimesFor(BLOBSTORE_BACKEND_LATENCY_METRIC_NAME)).hasSize(3).allSatisfy(timing -> assertThat(timing).isLessThan(delay));
}

