@Test
void readShouldReturnValidResultWhenDataMissingInOneNodeButPresentInOthers() throws IOException {
    int repeatCount = MULTIPLE_CHUNK_SIZE * CHUNK_SIZE;
    String longString = Strings.repeat("0123456789\n", repeatCount);
