@Test
void gcShouldSuccessWhenBatchSizeIsSmallerThanAllBlobEntries() {
    BlobStore blobStore = blobStore();
    int orphanBlobCount = 200;
    List<BlobId> referencedBlobIds = IntStream.range(0, 100).mapToObj(index -> Mono.from(blobStore.save(DEFAULT_BUCKET, UUID.randomUUID().toString(), BlobStore.StoragePolicy.HIGH_PERFORMANCE)).block()).toList();
    List<BlobId> orphanBlobIds = IntStream.range(0, orphanBlobCount).mapToObj(index -> Mono.from(blobStore.save(DEFAULT_BUCKET, UUID.randomUUID().toString(), BlobStore.StoragePolicy.HIGH_PERFORMANCE)).block()).toList();
    when(BLOB_REFERENCE_SOURCE.listReferencedBlobs()).thenReturn(Flux.fromIterable(referencedBlobIds));
    CLOCK.setInstant(NOW.plusMonths(2).toInstant());
    BloomFilterGCAlgorithm.Context context = new BloomFilterGCAlgorithm.Context(EXPECTED_BLOB_COUNT, ASSOCIATED_PROBABILITY);
    BloomFilterGCAlgorithm bloomFilterGCAlgorithm = bloomFilterGCAlgorithm();
    Task.Result result = Mono.from(bloomFilterGCAlgorithm.gc(EXPECTED_BLOB_COUNT, DELETION_WINDOW_SIZE, ASSOCIATED_PROBABILITY, DEFAULT_BUCKET, context)).block();
    assertThat(result).isEqualTo(Task.Result.COMPLETED);
    BloomFilterGCAlgorithm.Context.Snapshot snapshot = context.snapshot();
    assertThat(snapshot.getReferenceSourceCount()).isEqualTo(referencedBlobIds.size());
    assertThat(snapshot.getBlobCount()).isEqualTo(referencedBlobIds.size() + orphanBlobIds.size());
    assertThat(snapshot.getGcedBlobCount()).isLessThanOrEqualTo(orphanBlobIds.size()).isGreaterThan(0);
}

