        softly.assertThat(quotaUsageUpdatedEvent.getUsername()).isEqualTo(ALICE);
        softly.assertThat(quotaUsageUpdatedEvent.getQuotaRoot()).isEqualTo(quotaRootResolver.forUser(ALICE));
    });
