    Duration windowDuration = Duration.ofMillis(100);
    Stopwatch stopwatch = Stopwatch.createUnstarted();
    ImmutableList<Long> windowMembership = Flux.range(0, 10).transform(ReactorUtils.<Integer, Long>throttle().elements(windowMaxSize).per(windowDuration).forOperation(i -> Mono.fromCallable(() -> stopwatch.elapsed(TimeUnit.MILLISECONDS)))).map(i -> i / 100).doOnSubscribe(signal -> stopwatch.start()).collect(ImmutableList.toImmutableList()).block();
