    // Combined with slow operations, this ensures we are not filling up intermediate buffers.
    int windowMaxSize = 3_000;
    Duration windowDuration = Duration.ofMillis(100);
    assertThatCode(() -> Flux.range(0, 10_000).transform(ReactorUtils.<Integer, Long>throttle().elements(windowMaxSize).per(windowDuration).forOperation(i -> Mono.delay(windowDuration.multipliedBy(2)))).blockLast()).doesNotThrowAnyException();
