@Test
void throttleDownStreamConcurrencyShouldNotExceedWindowMaxSize() {
    int windowMaxSize = 3;
    Duration windowDuration = Duration.ofMillis(100);
    AtomicInteger ongoingProcessing = new AtomicInteger();
    Flux<Integer> originalFlux = Flux.range(0, 10);
    Function<Integer, Publisher<Integer>> longRunningOperation = any -> Mono.fromCallable(ongoingProcessing::incrementAndGet).flatMap(i -> Mono.delay(windowDuration.multipliedBy(2)).thenReturn(i)).flatMap(i -> Mono.fromRunnable(ongoingProcessing::decrementAndGet).thenReturn(i));
    ImmutableList<Integer> ongoingProcessingUponComputationStart = originalFlux.transform(ReactorUtils.<Integer, Integer>throttle().elements(windowMaxSize).per(windowDuration).forOperation(longRunningOperation)).collect(ImmutableList.toImmutableList()).block();
    assertThat(ongoingProcessingUponComputationStart).allSatisfy(processingCount -> assertThat(processingCount).isLessThanOrEqualTo(windowMaxSize));
}

