    Flux<Long> originalFlux = Flux.interval(Duration.ofMillis(10));
    ImmutableList<Long> perWindowCount = originalFlux.transform(ReactorUtils.<Long, Long>throttle().elements(windowMaxSize).per(windowDuration).forOperation(i -> Mono.fromCallable(() -> stopwatch.elapsed(TimeUnit.MILLISECONDS)))).map(i -> i / 20).doOnSubscribe(signal -> stopwatch.start()).take(10).groupBy(Function.identity()).flatMap(Flux::count).collect(ImmutableList.toImmutableList()).block();
