@Test
void containsShouldBeCached(CassandraCluster cassandra) throws DomainListException {
    domainList.addDomain(domain1);
    StatementRecorder statementRecorder = cassandra.getConf().recordStatements();
    Flux.range(0, 10).doOnNext(Throwing.consumer(i -> domainList.containsDomain(domain1))).blockLast();
    assertThat(statementRecorder.listExecutedStatements(StatementRecorder.Selector.preparedStatement("SELECT domain FROM domains WHERE domain=:domain"))).hasSize(1);
}

@Test
void cacheShouldBeRefreshedPeriodicallyUnderReadLoad(CassandraCluster cassandra) throws DomainListException {
    domainList.addDomain(domain1);
    StatementRecorder statementRecorder = cassandra.getConf().recordStatements();
    Flux.range(0, 6).delayElements(Duration.ofMillis(500)).flatMap(Throwing.function(i -> Mono.fromCallable(() -> domainList.containsDomain(domain1)).subscribeOn(Schedulers.boundedElastic()))).subscribeOn(Schedulers.newSingle("test")).blockLast();
    assertThat(statementRecorder.listExecutedStatements(StatementRecorder.Selector.preparedStatement("SELECT domain FROM domains WHERE domain=:domain"))).hasSizeBetween(2, 3);
}

