    ConcurrentTestRunner.builder().operation((threadNumber, step) -> migration.apply()).threadCount(THREAD_COUNT).operationCount(OPERATION_COUNT).runSuccessfullyWithin(Duration.ofMinutes(1));
    assertThat(cassandraMappingsSourcesDAO.retrieveSources(MAPPING).collectList().block()).hasSize(MAPPING_COUNT);
}

