@Test
default void concurrentStoreShouldOverrideOldValueWhenSameMessageId() throws Exception {
    int threadCount = 10;
    int stepCount = 100;
    ConcurrentHashMap<Integer, MessageId> messageIds = new ConcurrentHashMap<>();
    IntStream.range(0, threadCount).forEach(thread -> messageIds.put(thread, newMessageId()));
    ConcurrentTestRunner.builder().reactorOperation((thread, step) -> testee().store(messageIds.get(thread), MessageFastViewPrecomputedProperties.builder().preview(Preview.from(String.valueOf(step))).hasAttachment().build())).threadCount(threadCount).operationCount(stepCount).runSuccessfullyWithin(Duration.ofMinutes(1));
    IntStream.range(0, threadCount).forEach(index -> assertThat(Mono.from(testee().retrieve(messageIds.get(index))).block()).isEqualTo(MessageFastViewPrecomputedProperties.builder().preview(Preview.from(String.valueOf(stepCount - 1))).hasAttachment().build()));
}

@Test
default void storeShouldReturnAnyLatestPreviewOnConcurrentUpdate() throws Exception {
    MessageId messageId = newMessageId();
    ConcurrentTestRunner.builder().reactorOperation((thread, step) -> testee().store(messageId, MessageFastViewPrecomputedProperties.builder().preview(Preview.from(thread + "-" + step)).hasAttachment().build())).threadCount(10).operationCount(100).runSuccessfullyWithin(Duration.ofMinutes(1));
    String previewAsString = Mono.from(testee().retrieve(messageId)).block().getPreview().getValue();
    assertThat(previewAsString).describedAs("Ensure the stored result was generated by the last operation of one of the threads").isIn("0-99", "1-99", "2-99", "3-99", "4-99", "5-99", "6-99", "7-99", "8-99", "9-99");
}

