    // ALICE_OLD can access ANDRE account
    Mono.from(delegationStore.addAuthorizedUser(ALICE_OLD).forUser(ANDRE)).block();
    Mono.from(testee.changeUsername(ALICE_OLD, ALICE_NEW)).block();
    SoftAssertions.assertSoftly(softly -> {
        // Check delegatees of ALICE_OLD (make sure it is truncated)
        softly.assertThat(Flux.from(delegationStore.authorizedUsers(ALICE_OLD)).collectList().block()).isEmpty();
        // Check delegators of ALICE_OLD (make sure it is truncated)
        softly.assertThat(Flux.from(delegationStore.delegatedUsers(ALICE_OLD)).collectList().block()).isEmpty();
        // Check delegatees of ANDRE (make sure ANDRE delegatees do not contain ALICE_OLD)
        softly.assertThat(Flux.from(delegationStore.authorizedUsers(ANDRE)).collectList().block()).doesNotContain(ALICE_OLD);
        // Check delegators of BOB (make sure BOB delegators do not contain ALICE_OLD)
        softly.assertThat(Flux.from(delegationStore.delegatedUsers(BOB)).collectList().block()).doesNotContain(ALICE_OLD);
    });
}

