@Test
void shouldRejectInvalidAddressesUponSubmission(@TempDir File temporaryFolder) throws Exception {
    /*
        a..b@domain.com triggered a parsing error within jakarta.mail, the exception was ignored and substituted with null,
        resulting in a NPE in RemoteDelivery. Instead we now reject it as part of SMTP reception emails we cannot handle.
        This could be used to make the delivery of all remote recipients fail while local recipient succeeds.
         */
    InMemoryDNSService inMemoryDNSService = new InMemoryDNSService().registerMxRecord(JAMES_ANOTHER_DOMAIN, fakeSmtp.getContainer().getContainerIp());
    jamesServer = TemporaryJamesServer.builder().withBase(SMTP_ONLY_MODULE).withOverrides(binder -> binder.bind(DNSService.class).toInstance(inMemoryDNSService)).withMailetContainer(TemporaryJamesServer.simpleMailetContainerConfiguration().putProcessor(directResolutionTransport()).putProcessor(CommonProcessors.bounces())).withSmtpConfiguration(SmtpConfiguration.builder().doNotVerifyIdentity().withAutorizedAddresses("0.0.0.0/0.0.0.0")).build(temporaryFolder);
    jamesServer.start();
    dataProbe = jamesServer.getProbe(DataProbeImpl.class);
    dataProbe.addDomain(DEFAULT_DOMAIN);
    dataProbe.addUser(FROM, PASSWORD);
    assertThatThrownBy(() -> messageSender.connect(LOCALHOST_IP, jamesServer.getProbe(SmtpGuiceProbe.class).getSmtpPort()).sendMessage(FROM, "to..user@" + JAMES_ANOTHER_DOMAIN)).isInstanceOf(SMTPSendingException.class).hasMessageContaining("Error upon step RCPT: 553 5.1.3 Syntax error in recipient address");
}

