@Test
void mailFromShouldBePreservedUponConcurrency(@TempDir File temporaryFolder) throws Exception {
    String gatewayProperty = fakeSmtp.getContainer().getContainerIp();
    jamesServer = TemporaryJamesServer.builder().withBase(SMTP_ONLY_MODULE).withMailetContainer(generateMailetContainerConfiguration(gatewayProperty)).withSmtpConfiguration(SmtpConfiguration.builder().doNotVerifyIdentity().withAutorizedAddresses("0.0.0.0/0.0.0.0").build()).build(temporaryFolder);
    jamesServer.start();
    dataProbe = jamesServer.getProbe(DataProbeImpl.class);
    dataProbe.addDomain(DEFAULT_DOMAIN);
    dataProbe.addUser(FROM, PASSWORD);
    messageSender.connect(LOCALHOST_IP, jamesServer.getProbe(SmtpGuiceProbe.class).getSmtpPort());
    int mailCount = 100;
    IntStream.range(0, mailCount).forEach(Throwing.intConsumer(i -> messageSender.sendMessageWithHeaders("from" + i + "@" + DEFAULT_DOMAIN, ImmutableList.of(RECIPIENT), "Subject: " + i + "\r\n\r\nBODY")));
    awaitAtMostOneMinute.untilAsserted(() -> fakeSmtp.assertEmailReceived(response -> response.body("", hasSize(100))));
    fakeSmtp.assertEmailReceived(response -> {
        List<Map<String, Object>> receivedMails = response.extract().body().jsonPath().getList("");
        receivedMails.stream().forEach(map -> assertThat(map.get("from")).isEqualTo("from" + map.get("subject") + "@" + DEFAULT_DOMAIN));
    });
}

