@Test
void recipientsShouldBePublishedToAmqpWhenSendingEmailWithExchangeTypeFanoutConfiguration(@TempDir File temporaryFolder) throws Exception {
    // Given AmqpForwardAttribute mailet configured with exchange type fanout
    String exchangeName = "collector:email" + UUID.randomUUID();
    String routingKey = "routing1" + UUID.randomUUID();
    MailetConfiguration amqpForwardAttributeMailet = MailetConfiguration.builder().matcher(All.class).mailet(AmqpForwardAttribute.class).addProperty(AmqpForwardAttribute.URI_PARAMETER_NAME, amqpExtension.getAmqpUri()).addProperty(AmqpForwardAttribute.EXCHANGE_PARAMETER_NAME, exchangeName).addProperty(AmqpForwardAttribute.EXCHANGE_TYPE_PARAMETER_NAME, BuiltinExchangeType.FANOUT.getType()).addProperty(AmqpForwardAttribute.ATTRIBUTE_PARAMETER_NAME, EXTRACT_ATTRIBUTE).build();
    buildJameServer(temporaryFolder, amqpForwardAttributeMailet);
    Channel channel = rabbitMQConnection.createChannel();
    String queueName = channel.queueDeclare().getQueue();
    channel.queueBind(queueName, exchangeName, routingKey);
    // when sending an email
