@Test
void isMdnSentAutomaticallyShouldDetectBigMDN() throws Exception {
    MimeMessage message = MimeMessageUtil.defaultMimeMessage();
    MimeMultipart multipart = new MimeMultipart();
    multipart.setSubType("report");
    MimeBodyPart scriptPart = new MimeBodyPart();
    scriptPart.setDataHandler(new DataHandler(new ByteArrayDataSource(Joiner.on("\r\n").join("Final-Recipient: rfc822;any@any.com", "Disposition: automatic-action/MDN-sent-automatically; displayed", ""), "message/disposition-notification;")));
    scriptPart.setHeader("Content-Type", "message/disposition-notification");
    BodyPart bigBody = // ~3MB
    MimeMessageBuilder.bodyPartBuilder().data("12345678\r\n".repeat(300 * 1024)).build();
    multipart.addBodyPart(bigBody);
    multipart.addBodyPart(scriptPart);
    message.setContent(multipart);
    message.saveChanges();
    FakeMail fakeMail = FakeMail.builder().name("mail").sender(MailAddressFixture.ANY_AT_JAMES).mimeMessage(message).build();
    assertThat(new AutomaticallySentMailDetectorImpl().isMdnSentAutomatically(fakeMail)).isTrue();
}

