@ValueSource(strings = { "2024-07-01T07:00:00.00Z", "2024-07-01T10:15:30.00Z", "2024-07-01T18:00:00.00Z", "2024-07-01T18:00:00.01Z", "2024-07-01T20:00:00.00Z" })
