    FakeMail mail = FakeMail.builder().name("aMail").state(Mail.DEFAULT).build();
    testee.service(mail);
    SoftAssertions.assertSoftly(softly -> {
        softly.assertThat(mail.getState()).isEqualTo(Mail.GHOST);
        softly.assertThat(mailetContext.getSentMails()).hasSize(1);
        softly.assertThat(mailetContext.getSentMails().get(0).getDelay().get()).isEqualTo(new FakeMailContext.Delay(Duration.between(ZonedDateTime.ofInstant(now, zone), // 7am on next monday besides time change
