@Test
void envIdShouldBePositioned() throws Exception {
    FakeMailetConfig mailetConfig = FakeMailetConfig.builder().mailetName(MAILET_NAME).mailetContext(fakeMailContext).build();
    dsnBounce.init(mailetConfig);
    MailAddress senderMailAddress = new MailAddress("sender@domain.com");
    FakeMail mail = FakeMail.builder().name(MAILET_NAME).sender(senderMailAddress).attribute(DELIVERY_ERROR_ATTRIBUTE).mimeMessage(MimeMessageBuilder.mimeMessageBuilder().setText("My content")).recipient("recipient@domain.com").lastUpdated(Date.from(Instant.parse("2016-09-08T14:25:52.000Z"))).remoteAddr("remoteHost").build();
    mail.setDsnParameters(DsnParameters.builder().envId(DsnParameters.EnvId.of("xyz")).build().get());
    dsnBounce.service(mail);
    String expectedContent = "Reporting-MTA: dns; myhost\n" + "Received-From-MTA: dns; 111.222.333.444\n" + "Original-Envelope-Id: xyz\n" + "\n" + "Final-Recipient: rfc822; recipient@domain.com\n" + "Action: failed\n" + "Status: Delivery error\n" + "Diagnostic-Code: X-James; Delivery error\n" + "Last-Attempt-Date: Thu, 8 Sep 2016 14:25:52 +0000\n";
    List<SentMail> sentMails = fakeMailContext.getSentMails();
    assertThat(sentMails).hasSize(1);
    SentMail sentMail = sentMails.get(0);
    MimeMessage sentMessage = sentMail.getMsg();
    MimeMultipart content = (MimeMultipart) sentMessage.getContent();
    SharedByteArrayInputStream actualContent = (SharedByteArrayInputStream) content.getBodyPart(1).getContent();
    assertThat(IOUtils.toString(actualContent, StandardCharsets.UTF_8)).isEqualTo(expectedContent);
}

