    FakeMailetConfig mailetConfig = FakeMailetConfig.builder().mailetName(MAILET_NAME).mailetContext(fakeMailContext).setProperty("action", "relayed").setProperty("messageString", "Hi. Your mail was relayed at [machine].\n").build();
    dsnBounce.init(mailetConfig);
    MailAddress senderMailAddress = new MailAddress("sender@domain.com");
    FakeMail mail = FakeMail.builder().name(MAILET_NAME).sender(senderMailAddress).attribute(DELIVERY_ERROR_ATTRIBUTE).mimeMessage(MimeMessageBuilder.mimeMessageBuilder().setText("My content")).recipient("recipient@domain.com").lastUpdated(Date.from(Instant.parse("2016-09-08T14:25:52.000Z"))).build();
    dsnBounce.service(mail);
    String hostname = InetAddress.getLocalHost().getHostName();
    String expectedContent = "Hi. Your mail was relayed at " + hostname + ".\n" + "\n" + "Relayed recipient(s):\n" + "recipient@domain.com\n" + "\n";
    List<SentMail> sentMails = fakeMailContext.getSentMails();
    assertThat(sentMails).hasSize(1);
    SentMail sentMail = sentMails.get(0);
    MimeMessage sentMessage = sentMail.getMsg();
    MimeMultipart content = (MimeMultipart) sentMessage.getContent();
    BodyPart bodyPart = content.getBodyPart(0);
    assertThat(bodyPart.getContentType()).isEqualTo("text/plain; charset=us-ascii");
    assertThat(bodyPart.getContent()).isEqualTo(expectedContent);
}

@Test
void serviceShouldSendMultipartMailContainingDSNPart() throws Exception {
