    dsnBounce.service(mail);
    String expectedContent = "Reporting-MTA: dns; myhost\n" + "Received-From-MTA: dns; 111.222.333.444\n" + "\n" + "Final-Recipient: rfc822; recipient@domain.com\n" + "Action: relayed\n" + "Status: unknown\n" + "Last-Attempt-Date: Thu, 8 Sep 2016 14:25:52 +0000\n";
