@Test
void initializeDateIfNotPresentShouldNotThrow() throws Exception {
    MailImpl mail = MailImpl.builder().name("name").build();
    MimeMessage mimeMessage = MimeMessageBuilder.mimeMessageBuilder().setText("My content").build();
    mail.setMessage(mimeMessage);
    mail.getMessage().removeHeader("Date");
    assertThatCode(() -> MailModifier.builder().mailet(mock(RedirectNotify.class)).mail(mail).dns(mock(DNSService.class)).build().initializeDateIfNotPresent()).doesNotThrowAnyException();
}

