@Test
void matchShouldAttachMatchingRuleNameToMail() throws Exception {
    String attributeValue = "should match sender";
    Dlp dlp = new Dlp(asRulesLoaderFor(JAMES_APACHE_ORG_DOMAIN, DlpDomainRules.builder().recipientRule(Id.of("should not match recipient"), Pattern.compile(RECIPIENT3.asString())).senderRule(Id.of(attributeValue), Pattern.compile(JAMES_APACHE_ORG)).build()), new NoopGaugeRegistry());
    FakeMail mail = FakeMail.builder().name("name").sender(ANY_AT_JAMES).recipient(RECIPIENT1).recipient(RECIPIENT2).build();
    dlp.match(mail);
    AttributeName name = AttributeName.of("DlpMatchedRule");
    assertThat(mail.getAttribute(name)).contains(new Attribute(name, AttributeValue.of(attributeValue)));
}

