@ParameterizedTest
void remoteDeliveryCouldBreakDKIMSignWhenTextMessageWhenEnable8BitMime(String mailName, String emlPath, SMTPMessageSender messageSender, DockerMockSmtp dockerMockSmtp) throws Exception {
    InMemoryDNSService inMemoryDNSService = new InMemoryDNSService().registerMxRecord(JAMES_ANOTHER_DOMAIN, dockerMockSmtp.getIPAddress());
    jamesServer = TemporaryJamesServer.builder().withBase(SMTP_ONLY_MODULE).withOverrides(binder -> binder.bind(DNSService.class).toInstance(inMemoryDNSService)).withSmtpConfiguration(SmtpConfiguration.builder().withAutorizedAddresses("0.0.0.0/0.0.0.0")).withMailetContainer(TemporaryJamesServer.simpleMailetContainerConfiguration().putProcessor(directResolutionTransport(MailetConfiguration.remoteDeliveryBuilder().addProperty("mail.smtp.allow8bitmime", "true"))).putProcessor(CommonProcessors.bounces())).build(tempDir);
    jamesServer.start();
    dataProbe = jamesServer.getProbe(DataProbeImpl.class);
    dataProbe.addDomain(DEFAULT_DOMAIN);
    dataProbe.addUser(FROM, PASSWORD);
    FakeMail mail = FakeMail.builder().name(mailName).sender(new MailAddress(FROM)).recipient(new MailAddress(RECIPIENT)).mimeMessage(MimeMessageUtil.mimeMessageFromStream(ClassLoader.getSystemResourceAsStream(emlPath))).build();
    messageSender.connect(LOCALHOST_IP, jamesServer.getProbe(SmtpGuiceProbe.class).getSmtpPort()).sendMessage(mail);
    MimeMessage sendMessage = toMimeMessage(getFirstRecivedMail(dockerMockSmtp));
    assertThatThrownBy(() -> dkimVerifier.verifyUsingCRLF(sendMessage)).isInstanceOf(PermFailException.class).hasMessageContaining("Computed bodyhash is different from the expected one");
}

