@Test
void appendingAOutdatedMessageInOutBoxShouldNotAddItToTheView() throws Exception {
    EmailQueryViewManager emailQueryView = new DefaultEmailQueryViewManager(new MemoryEmailQueryView());
    PopulateEmailQueryViewListener queryViewListener = new PopulateEmailQueryViewListener(messageIdManager, emailQueryView, sessionProvider);
    MailboxPath outboxPath = MailboxPath.forUser(BOB, "Outbox");
    MailboxId outboxId = mailboxManager.createMailbox(outboxPath, mailboxSession).orElseThrow();
    // given: save a message in Inbox
    ComposedMessageId composedId = inboxMessageManager.appendMessage(MessageManager.AppendCommand.builder().withInternalDate(Date.from(ZonedDateTime.parse("2014-10-30T15:12:00Z").toInstant())).build(emptyMessage(Date.from(ZonedDateTime.parse("2014-10-30T14:12:00Z").toInstant()))), mailboxSession).getId();
    // mock an outDated message by assigning above message in OutBox
    MessageMetaData outdatedMessageMetaData = new MessageMetaData(MessageUid.of(1), ModSeq.of(35), new Flags(), 12, new Date(), Optional.empty(), composedId.getMessageId(), ThreadId.fromBaseMessageId(composedId.getMessageId()));
    // the latest mailboxId should be `composedId.getMailboxId()`, not `outboxId`
    MailboxEvents.Added addedOutDatedEvent = new MailboxEvents.Added(MailboxSession.SessionId.of(42), BOB, outboxPath, outboxId, ImmutableSortedMap.of(MessageUid.of(1), outdatedMessageMetaData), Event.EventId.random(), !IS_DELIVERY, !IS_APPENDED, Optional.empty());
    Mono.from(queryViewListener.reactiveEvent(addedOutDatedEvent)).block();
    assertThat(viewManager.getEmailQueryView(mailboxSession.getUser()).listMailboxContentSortedBySentAt(outboxId, Limit.limit(12)).collectList().block()).isEmpty();
}

