void shouldSupportSentDateAndIsNewerThan(JMAPFilteringTestSystem testSystem) throws Exception {
    Mono.from(testSystem.getFilteringManagement().defineRulesForUser(RECIPIENT_1_USERNAME, Optional.empty(), Rule.builder().id(Rule.Id.of("1")).name("rule 1").conditionGroup(Rule.Condition.of(SENT_DATE, IS_NEWER_THAN, "7d")).action(Rule.Action.of(Rule.Action.AppendInMailboxes.withMailboxIds(testSystem.getRecipient1MailboxId().serialize()))).build())).block();
    FakeMail oldMail = testSystem.asMail(mimeMessageBuilder().addHeader(FROM.asString(), USER_2_ADDRESS).addHeader(SUBJECT.asString(), "abcdef").setDate(Clock.systemUTC().instant().minus(Duration.ofDays(10))));
    FakeMail newMail = testSystem.asMail(mimeMessageBuilder().addHeader(FROM.asString(), USER_2_ADDRESS).addHeader(SUBJECT.asString(), "abcdef").setDate(Clock.systemUTC().instant().minus(Duration.ofDays(5))));
    testSystem.getJmapFiltering().service(oldMail);
    testSystem.getJmapFiltering().service(newMail);
    assertThatAttribute(newMail.getAttribute(RECIPIENT_1_USERNAME_ATTRIBUTE_NAME)).isEqualTo(RECIPIENT_1_MAILBOX_1_ATTRIBUTE);
    assertThat(oldMail.getAttribute(RECIPIENT_1_USERNAME_ATTRIBUTE_NAME)).isEmpty();
}

