@Test
void imapSearchShouldSupportThreadId() throws Exception {
    MailboxSession mailboxSession = memoryIntegrationResources.getMailboxManager().createSystemSession(USER);
    memoryIntegrationResources.getMailboxManager().createMailbox(MailboxPath.inbox(USER), mailboxSession);
    MessageManager.AppendResult appendResult = memoryIntegrationResources.getMailboxManager().getMailbox(MailboxPath.inbox(USER), mailboxSession).appendMessage(MessageManager.AppendCommand.builder().build("MIME-Version: 1.0
" + "Content-Type: text/html; charset=UTF-8
" + "Content-Transfer-Encoding: quoted-printable
" + "From: =?ISO-8859-1?Q?Beno=EEt_TELLIER?= <b@linagora.com>
" + "Sender: =?ISO-8859-1?Q?Beno=EEt_TELLIER?= <b@linagora.com>
" + "Reply-To: b@linagora.com
" + "To: =?ISO-8859-1?Q?Beno=EEt_TELLIER?= <b@linagora.com>
" + "Subject: Test utf-8 charset
" + "Message-ID: <Mime4j.5f1.9a40f68264d6f2fa.17876fb5605@linagora.com>
" + "Date: Sun, 28 Mar 2021 03:58:06 +0000
" + "
" + "<p>=E5=A4=A9=E5=A4=A9=E5=90=91=E4=B8=8A<br></p>
"), mailboxSession);
    clientConnection.write(ByteBuffer.wrap(String.format("a0 LOGIN %s %s
", USER.asString(), USER_PASS).getBytes(StandardCharsets.UTF_8)));
    readStringUntil(clientConnection, s -> s.contains("a0 OK"));
    clientConnection.write(ByteBuffer.wrap("a1 SELECT INBOX
".getBytes(StandardCharsets.UTF_8)));
    readStringUntil(clientConnection, s -> s.contains("a1 OK"));
    clientConnection.write(ByteBuffer.wrap(String.format("a2 UID SEARCH THREADID %s
", appendResult.getThreadId().serialize()).getBytes(StandardCharsets.UTF_8)));
    readStringUntil(clientConnection, s -> s.contains(("* SEARCH " + appendResult.getId().getUid().asLong())));
}

