    connection.addHandlerFirst(new JdkZlibDecoder(ZlibWrapper.ZLIB_OR_NONE));
    connection.addHandlerFirst(new JdkZlibEncoder(ZlibWrapper.NONE, 5));
    send("a2 SELECT INBOX\r\n");
