    responses.clear();
    send("a3 IDLE\r\n");
    Awaitility.await().until(() -> responses.stream().anyMatch(s -> s.contains("+ Idling")));
    // No pollution
    assertThat(responses).hasSize(1);
    responses.clear();
    send("DONE\r\n");
    Awaitility.await().until(() -> responses.stream().anyMatch(s -> s.contains("a3 OK IDLE completed.")));
    // No pollution
    assertThat(responses).hasSize(1);
}

