    if (!mailboxManager.mailboxExists(mailboxPath, session).block()) {
        mailboxManager.createMailbox(mailboxPath, session);
    }
    int msgCount = 100;
    for (int i = 0; i < msgCount; i++) {
        mailboxManager.getMailbox(mailboxPath, session).appendMessage(MessageManager.AppendCommand.from(Message.Builder.of().setSubject("test").setBody(String.valueOf(i), StandardCharsets.UTF_8)), session);
