@Test
void gcTaskShouldSuccessWhenMixCase() {
    List<BlobId> referencedBlobIds = IntStream.range(0, 100).mapToObj(index -> Mono.from(blobStore.save(DEFAULT_BUCKET, UUID.randomUUID().toString(), BlobStore.StoragePolicy.HIGH_PERFORMANCE)).block()).collect(Collectors.toList());
    List<BlobId> orphanBlobIds = IntStream.range(0, 50).mapToObj(index -> Mono.from(blobStore.save(DEFAULT_BUCKET, UUID.randomUUID().toString(), BlobStore.StoragePolicy.HIGH_PERFORMANCE)).block()).collect(Collectors.toList());
    when(blobReferenceSource.listReferencedBlobs()).thenReturn(Flux.fromIterable(referencedBlobIds));
    clock.setInstant(TIMESTAMP.plusMonths(2).toInstant());
    List<BlobId> unExpiredBlobIds = IntStream.range(0, 30).mapToObj(index -> Mono.from(blobStore.save(DEFAULT_BUCKET, UUID.randomUUID().toString(), BlobStore.StoragePolicy.HIGH_PERFORMANCE)).block()).collect(Collectors.toList());
