    given().basePath(TasksRoutes.BASE).when().get(taskId + "/await").then().body("status", is("completed")).body("additionalInformation.referenceSourceCount", is(referencedBlobIds.size())).body("additionalInformation.blobCount", is(referencedBlobIds.size() + orphanBlobIds.size() + unExpiredBlobIds.size())).body("additionalInformation.gcedBlobCount", Matchers.lessThanOrEqualTo(orphanBlobIds.size())).body("additionalInformation.errorCount", is(0));
