@Test
void shouldDeleteAllUsersDataOfTheDomain() throws UsersRepositoryException {
    // GIVEN localhost domain has 2 users
    usersRepository.addUser(Username.of("user1@localhost"), "secret");
    usersRepository.addUser(Username.of("user2@localhost"), "secret");
    // THEN delete all users data of localhost domain
    String taskId = with().basePath("/domains").queryParam("action", "deleteData").post("/localhost").jsonPath().get("taskId");
    given().basePath(TasksRoutes.BASE).when().get(taskId + "/await").then().body("type", is("DeleteUsersDataOfDomainTask")).body("status", is("completed")).body("additionalInformation.type", is("DeleteUsersDataOfDomainTask")).body("additionalInformation.domain", is("localhost")).body("additionalInformation.successfulUsersCount", is(2)).body("additionalInformation.failedUsersCount", is(0)).body("additionalInformation.failedUsers", empty());
    // then should delete data of the 2 users
    assertThat(recordProcessedUsersStep.processedUsers).containsExactlyInAnyOrder(Username.of("user1@localhost"), Username.of("user2@localhost"));
}

