@Test
void userReprocessingWithCorrectModeShouldReturnTaskDetailsWhenMails() throws Exception {
    MailboxSession systemSession = mailboxManager.createSystemSession(USERNAME);
    MailboxId mailboxId = mailboxManager.createMailbox(INBOX, systemSession).get();
    Mailbox mailbox = mailboxManager.getMailbox(mailboxId, systemSession).getMailboxEntity();
    ComposedMessageId result = mailboxManager.getMailbox(INBOX, systemSession).appendMessage(MessageManager.AppendCommand.builder().build("header: value\r\n\r\nbody"), systemSession).getId();
    mailboxManager.getMailbox(INBOX, systemSession).appendMessage(MessageManager.AppendCommand.builder().build("header: value\r\n\r\nbody"), systemSession);
    List<MessageResult> messages = messageIdManager.getMessages(ImmutableList.of(result.getMessageId()), FetchGroup.MINIMAL, systemSession);
    Flags newFlags = new Flags(Flags.Flag.DRAFT);
    UpdatedFlags updatedFlags = UpdatedFlags.builder().uid(result.getUid()).modSeq(messages.get(0).getModSeq()).oldFlags(new Flags()).newFlags(newFlags).build();
    // We update on the searchIndex level to try to create inconsistencies
    searchIndex.update(systemSession, mailbox.getMailboxId(), ImmutableList.of(updatedFlags)).block();
    String taskId = with().queryParam("task", "reIndex").queryParam("mode", "fixOutdated").post().jsonPath().get("taskId");
    given().basePath(TasksRoutes.BASE).when().get(taskId + "/await").then().body("status", Matchers.is("completed")).body("taskId", Matchers.is(notNullValue())).body("type", Matchers.is(UserReindexingTask.USER_RE_INDEXING.asString())).body("additionalInformation.successfullyReprocessedMailCount", Matchers.is(2)).body("additionalInformation.failedReprocessedMailCount", Matchers.is(0)).body("additionalInformation.runningOptions.messagesPerSecond", Matchers.is(50)).body("additionalInformation.runningOptions.mode", Matchers.is("FIX_OUTDATED")).body("startedDate", Matchers.is(notNullValue())).body("submitDate", Matchers.is(notNullValue())).body("completedDate", Matchers.is(notNullValue()));
}

@Test
void userReprocessingWithCorrectModeShouldFixInconsistenciesInES() throws Exception {
    MailboxSession systemSession = mailboxManager.createSystemSession(USERNAME);
    MailboxId mailboxId = mailboxManager.createMailbox(INBOX, systemSession).get();
    Mailbox mailbox = mailboxManager.getMailbox(mailboxId, systemSession).getMailboxEntity();
    ComposedMessageId result = mailboxManager.getMailbox(INBOX, systemSession).appendMessage(MessageManager.AppendCommand.builder().build("header: value\r\n\r\nbody"), systemSession).getId();
    Flags initialFlags = searchIndex.retrieveIndexedFlags(mailbox, result.getUid()).block();
    List<MessageResult> messages = messageIdManager.getMessages(ImmutableList.of(result.getMessageId()), FetchGroup.MINIMAL, systemSession);
    Flags newFlags = new Flags(Flags.Flag.DRAFT);
    UpdatedFlags updatedFlags = UpdatedFlags.builder().uid(result.getUid()).modSeq(messages.get(0).getModSeq()).oldFlags(new Flags()).newFlags(newFlags).build();
    // We update on the searchIndex level to try to create inconsistencies
    searchIndex.update(systemSession, mailbox.getMailboxId(), ImmutableList.of(updatedFlags)).block();
    String taskId = with().queryParam("task", "reIndex").queryParam("mode", "fixOutdated").post().jsonPath().get("taskId");
    given().basePath(TasksRoutes.BASE).when().get(taskId + "/await");
    assertThat(searchIndex.retrieveIndexedFlags(mailbox, result.getUid()).block()).isEqualTo(initialFlags);
}

