@Test
void retrievingAMailShouldDisplayItsInformation() throws Exception {
    MailRepository mailRepository = mailRepositoryStore.create(URL_MY_REPO);
    String name = NAME_1;
    String sender = "sender@domain";
    String recipient1 = "recipient1@domain";
    String recipient2 = "recipient2@domain";
    String state = "state";
    String errorMessage = "Error: why this mail is stored";
    String remoteHost = "smtp.domain";
    String remoteAddr = "66.66.66.66";
    Date lastUpdated = new Date(07060504030201L);
    mailRepository.store(FakeMail.builder().name(name).sender(sender).recipients(recipient1, recipient2).state(state).errorMessage(errorMessage).remoteHost(remoteHost).remoteAddr(remoteAddr).lastUpdated(lastUpdated).build());
    when().get(PATH_ESCAPED_MY_REPO + "/mails/" + name).then().statusCode(HttpStatus.OK_200).body("name", is(name)).body("sender", is(sender)).body("recipients", containsInAnyOrder(recipient1, recipient2)).body("state", is(state)).body("error", is(errorMessage)).body("remoteHost", is(remoteHost)).body("remoteAddr", is(remoteAddr)).body("lastUpdated", is(DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss.SSSZ").format(ZonedDateTime.ofInstant(lastUpdated.toInstant(), ZoneId.of("UTC")))));
}

@Test
void retrievingAMailShouldDisplayAllAdditionalFieldsWhenRequested() throws Exception {
    MailRepository mailRepository = mailRepositoryStore.create(URL_MY_REPO);
    String name = NAME_1;
    BodyPartBuilder textMessage = MimeMessageBuilder.bodyPartBuilder().addHeader("Content-type", "text/plain").data("My awesome body!!");
    BodyPartBuilder htmlMessage = MimeMessageBuilder.bodyPartBuilder().addHeader("Content-type", "text/html").data("My awesome <em>body</em>!!");
    MimeMessage mimeMessage = MimeMessageBuilder.mimeMessageBuilder().addHeader("headerName3", "value5").addHeader("headerName3", "value8").addHeader("headerName4", "value6").addHeader("headerName4", "value7").setContent(MimeMessageBuilder.multipartBuilder().subType("alternative").addBody(textMessage).addBody(htmlMessage)).build();
    MailAddress recipientHeaderAddress = new MailAddress("third@party");
    FakeMail mail = FakeMail.builder().name(name).attribute(Attribute.convertToAttribute("name1", "value1")).attribute(Attribute.convertToAttribute("name2", "value2")).mimeMessage(mimeMessage).size(42424242).addHeaderForRecipient(Header.builder().name("headerName1").value("value1").build(), recipientHeaderAddress).addHeaderForRecipient(Header.builder().name("headerName1").value("value2").build(), recipientHeaderAddress).addHeaderForRecipient(Header.builder().name("headerName2").value("value3").build(), recipientHeaderAddress).addHeaderForRecipient(Header.builder().name("headerName2").value("value4").build(), recipientHeaderAddress).build();
    mailRepository.store(mail);
    String jsonAsString = given().params("additionalFields", "attributes,headers,textBody,htmlBody,messageSize,perRecipientsHeaders").when().get(PATH_ESCAPED_MY_REPO + "/mails/" + NAME_1).then().extract().body().asString();
    assertThatJson(jsonAsString).when(IGNORING_ARRAY_ORDER).when(IGNORING_EXTRA_FIELDS).isEqualTo("{" + "  \"name\": \"name1\"," + "  \"sender\": null," + "  \"recipients\": []," + "  \"error\": null," + "  \"state\": null," + "  \"remoteHost\": \"111.222.333.444\"," + "  \"remoteAddr\": \"127.0.0.1\"," + "  \"lastUpdated\": null," + "  \"attributes\": {" + "    \"name2\": \"value2\"," + "    \"name1\": \"value1\"" + "  }," + "  \"perRecipientsHeaders\": {" + "    \"third@party\": {" + "      \"headerName1\": [" + "        \"value1\"," + "        \"value2\"" + "      ]," + "      \"headerName2\": [" + "        \"value3\"," + "        \"value4\"" + "      ]" + "    }" + "  }," + "  \"headers\": {" + "    \"headerName4\": [" + "      \"value6\"," + "      \"value7\"" + "    ]," + "    \"headerName3\": [" + "      \"value5\"," + "      \"value8\"" + "    ]" + "  }," + "  \"textBody\": \"My awesome body!!\"," + "  \"htmlBody\": \"My awesome <em>body</em>!!\"," + "  \"messageSize\": 42424242" + "}");
}

