@Test
void downloadingAMailShouldReturnTheEml() throws Exception {
    RestAssured.requestSpecification = new RequestSpecBuilder().setPort(webAdminServer.getPort().getValue()).setBasePath(MailRepositoriesRoutes.MAIL_REPOSITORIES).build();
    RestAssured.registerParser(Constants.RFC822_CONTENT_TYPE, Parser.TEXT);
    MailRepository mailRepository = mailRepositoryStore.create(URL_MY_REPO);
    String name = NAME_1;
    FakeMail mail = FakeMail.builder().name(name).fileName("mail.eml").build();
    mailRepository.store(mail);
    String expectedContent = ClassLoaderUtils.getSystemResourceAsString("mail.eml", StandardCharsets.UTF_8);
    String actualContent = given().accept(Constants.RFC822_CONTENT_TYPE).when().get(PATH_ESCAPED_MY_REPO + "/mails/" + name).then().statusCode(HttpStatus.OK_200).header("Content-Length", Integer.toString(expectedContent.length())).contentType(Constants.RFC822_CONTENT_TYPE).extract().body().asString();
    assertThat(actualContent).isEqualToNormalizingNewlines(expectedContent);
}

