@Test
void reprocessingAllTaskShouldResetLoopDetection() throws Exception {
    MailRepository mailRepository1 = mailRepositoryStore.create(URL_MY_REPO);
    MailRepository mailRepository2 = mailRepositoryStore.create(URL_MY_REPO_OTHER);
    FakeMail mail = FakeMail.builder().name(NAME_1).mimeMessage(MimeMessageUtil.mimeMessageFromBytes(MESSAGE_BYTES)).build();
    LoopPrevention.RecordedRecipients.fromMail(mail).merge(new MailAddress("bob@domain.tld")).recordOn(mail);
    mailRepository1.store(mail);
    String taskId = with().param("action", "reprocess").patch(PATH_ESCAPED_MY_REPO + "/mails").jsonPath().get("taskId");
    with().basePath(TasksRoutes.BASE).get(taskId + "/await");
    assertThat(spoolQueue.browse()).toIterable().extracting(ManageableMailQueue.MailQueueItemView::getMail).extracting(LoopPrevention.RecordedRecipients::fromMail).extracting(LoopPrevention.RecordedRecipients::getRecipients).allSatisfy(recordedRecipients -> assertThat(recordedRecipients).isEmpty());
}

