@Test
void shouldRecomputeMailboxCounters(GuiceJamesServer server) throws Exception {
    server.getProbe(TestingSessionProbe.class).getTestingSession().registerScenario(fail().forever().whenQueryStartsWith("UPDATE mailboxcounters SET count=count+1, unseen=unseen+"));
    smtpMessageSender.connect(LOCALHOST_IP, server.getProbe(SmtpGuiceProbe.class).getSmtpPort()).sendMessageWithHeaders(ALICE.asString(), BOB.asString(), MESSAGE);
    Awaitility.await().untilAsserted(() -> assertThat(server.getProbe(MailRepositoryProbeImpl.class).getRepositoryMailCount(MailRepositoryUrl.from("cassandra://var/mail/error/"))).isGreaterThanOrEqualTo(1));
