    testIMAPClient.connect(JAMES_SERVER_HOST, server.getProbe(ImapGuiceProbe.class).getImapPort()).login(BOB, BOB_PASSWORD).select(MailboxConstants.INBOX);
    assertThat(testIMAPClient.getMessageCount(MailboxConstants.INBOX)).isEqualTo(4);
}

@Test
void shouldRecomputeQuotas(GuiceJamesServer server) throws Exception {
    Barrier barrier1 = new Barrier();
    Barrier barrier2 = new Barrier();
    String updatedQuotaQueryString = "UPDATE quotacurrentvalue SET";
    server.getProbe(TestingSessionProbe.class).getTestingSession().registerScenario(// Event bus first execution
    awaitOn(barrier1).thenFail().times(1).whenQueryStartsWith(updatedQuotaQueryString), // scenari for event bus retry
    awaitOn(barrier2).thenFail().times(1).whenQueryStartsWith(updatedQuotaQueryString));
    smtpMessageSender.connect(LOCALHOST_IP, server.getProbe(SmtpGuiceProbe.class).getSmtpPort()).sendMessageWithHeaders(ALICE.asString(), BOB.asString(), MESSAGE);
    testIMAPClient.connect(JAMES_SERVER_HOST, server.getProbe(ImapGuiceProbe.class).getImapPort()).login(BOB, BOB_PASSWORD).select(MailboxConstants.INBOX).awaitMessage(Awaitility.await());
    // Await first execution
    barrier1.awaitCaller();
    barrier1.releaseCaller();
    // Await event bus retry
    barrier2.awaitCaller();
    barrier2.releaseCaller();
    String taskId = with().basePath("/quota/users").queryParam("task", "RecomputeCurrentQuotas").post().jsonPath().get("taskId");
    with().basePath(TasksRoutes.BASE).get(taskId + "/await");
    assertThat(testIMAPClient.getQuotaRoot(MailboxConstants.INBOX)).contains("* QUOTAROOT \"INBOX\" #private&bob@domain.tld\r\n" + "* QUOTA #private&bob@domain.tld (MESSAGE 1 50)");
}

