@Test
void shouldSolveMessagesDeletedInconsistency(GuiceJamesServer server) throws Exception {
    // Given a message and a messageDeleted inconsistency
    smtpMessageSender.connect(LOCALHOST_IP, server.getProbe(SmtpGuiceProbe.class).getSmtpPort()).sendMessageWithHeaders(ALICE.asString(), BOB.asString(), MESSAGE);
    Thread.sleep(1000);
    TestingSession testingSession = server.getProbe(TestingSessionProbe.class).getTestingSession();
    testIMAPClient.connect(JAMES_SERVER_HOST, server.getProbe(ImapGuiceProbe.class).getImapPort()).login(BOB, BOB_PASSWORD).select(MailboxConstants.INBOX).awaitMessage(Awaitility.await());
    testIMAPClient.setFlagsForAllMessagesInMailbox("\\Deleted");
    // Make sure messageDeleted inconsistency is present
    testingSession.execute("TRUNCATE messagedeleted");
    // When we run solveInconsistenciesTask
    String solveInconsistenciesTaskId = with().queryParam("task", "SolveMessageDeletedInconsistencies").post("/mailboxes").jsonPath().get("taskId");
    // Then task details should be as expected
    with().basePath(TasksRoutes.BASE).get(solveInconsistenciesTaskId + "/await").then().body("status", is("completed")).body("type", is("solve-mailbox-flag-inconsistencies")).body("additionalInformation.targetFlag", is("DELETED")).body("additionalInformation.processedMailboxEntries", is(1));
    // And messageDeleted inconsistency should be solved
    assertThat(testingSession.execute("SELECT * FROM messageDeleted").getAvailableWithoutFetching()).isEqualTo(1);
}

