@Test
void shouldAdaptQuotas(GuiceJamesServer server) throws Exception {
    server.getProbe(MailboxProbeImpl.class).createMailbox(MailboxPath.inbox(BOB));
    QuotaProbesImpl quotaProbes = server.getProbe(QuotaProbesImpl.class);
    QuotaRoot bobQuotaRoot = quotaProbes.getQuotaRoot(MailboxPath.inbox(BOB));
    quotaProbes.setMaxMessageCount(bobQuotaRoot, QuotaCountLimit.count(50));
    quotaProbes.setMaxStorage(bobQuotaRoot, QuotaSizeLimit.size(1000));
    server.getProbe(MailboxProbeImpl.class).appendMessage(BOB.asString(), MailboxPath.inbox(BOB), MessageManager.AppendCommand.from(Message.Builder.of().setSubject("test").setBody("testmail", StandardCharsets.UTF_8).build()));
    Awaitility.await().atMost(TEN_SECONDS).untilAsserted(() -> {
        assertThat(quotaProbes.getMessageCountQuota(bobQuotaRoot).getUsed().asLong()).isEqualTo(1L);
        assertThat(quotaProbes.getStorageQuota(bobQuotaRoot).getUsed().asLong()).isEqualTo(85L);
    });
    String taskId = webAdminApi.queryParam("action", "rename").post("/users/" + BOB.asString() + "/rename/" + ALICE.asString()).jsonPath().get("taskId");
    webAdminApi.get("/tasks/" + taskId + "/await").then().statusCode(HttpStatus.SC_OK).body("additionalInformation.status.QuotaUsernameChangeTaskStep", Matchers.is("DONE"));
    QuotaRoot aliceQuotaRoot = quotaProbes.getQuotaRoot(MailboxPath.inbox(ALICE));
    assertSoftly(softly -> {
        softly.assertThat(Throwing.supplier(() -> quotaProbes.getMessageCountQuota(aliceQuotaRoot)).get()).isEqualTo(Quota.<QuotaCountLimit, QuotaCountUsage>builder().used(QuotaCountUsage.count(1)).computedLimit(QuotaCountLimit.count(50)).build());
        softly.assertThat(Throwing.supplier(() -> quotaProbes.getStorageQuota(aliceQuotaRoot)).get()).isEqualTo(Quota.<QuotaSizeLimit, QuotaSizeUsage>builder().used(QuotaSizeUsage.size(85)).computedLimit(QuotaSizeLimit.size(1000)).build());
    });
}

