@Test
void restoreDeletedMessageShouldSucceed(GuiceJamesServer jamesServer) throws Exception {
    // Create a message
    int imapPort = jamesServer.getProbe(ImapGuiceProbe.class).getImapPort();
    smtpMessageSender.connect(JAMES_SERVER_HOST, jamesServer.getProbe(SmtpGuiceProbe.class).getSmtpPort()).authenticate(USER, PASSWORD).sendMessageWithHeaders(USER, USER, "Subject: thisIsASubject\r\n\r\nBody");
    testIMAPClient.connect(JAMES_SERVER_HOST, imapPort).login(USER, PASSWORD).select(TestIMAPClient.INBOX).awaitMessageCount(AWAIT, 1);
    // Delete the message
    testIMAPClient.setFlagsForAllMessagesInMailbox("\\Deleted");
    testIMAPClient.expunge();
    testIMAPClient.awaitNoMessage(AWAIT);
    // Restore the message using the Deleted message vault webadmin endpoint
    String restoreBySubjectQuery = "{" + "  \"combinator\": \"and\"," + "  \"limit\": 1," + "  \"criteria\": [" + "    {" + "      \"fieldName\": \"subject\"," + "      \"operator\": \"equals\"," + "      \"value\": \"thisIsASubject\"" + "    }" + "  ]" + "}";
    DeletedMessagesVaultRequests.restoreMessagesForUserWithQuery(webAdminApi, USER, restoreBySubjectQuery);
    // await the message to be restored
    testIMAPClient.select(DefaultMailboxes.RESTORED_MESSAGES).awaitMessageCount(AWAIT, 1);
}

