@Tag(BasicFeature.TAG)
@Test
public void quotaSearchShouldPlayWellWithDelegation(GuiceJamesServer server) throws Exception {
    // GIVEN two users with 0/20 mails quota
    webAdminApi.body("20").put("/quota/users/" + BOB.asString() + "/count");
    webAdminApi.body("20").put("/quota/users/" + CEDRIC.asString() + "/count");
    // AND CEDRIC delegates his mailbox to BOB
    MailboxId mailboxId = server.getProbe(MailboxProbeImpl.class).createMailbox(MailboxPath.inbox(CEDRIC));
    server.getProbe(ACLProbeImpl.class).replaceRights(MailboxPath.inbox(CEDRIC), BOB.asString(), MailboxACL.FULL_RIGHTS);
    // WHEN BOB adds 19 message to CEDRIC mailbox
    String accountId = Hashing.sha256().hashString(BOB.asString(), StandardCharsets.UTF_8).toString();
    String requestBody = "{" + "  \"using\": [\"urn:ietf:params:jmap:core\", \"urn:ietf:params:jmap:mail\"]," + "  \"methodCalls\": [" + "    [\"Email/set\", " + "      {" + "         \"accountId\": \"" + accountId + "\"," + "         \"create\": {" + "           \"aaaaaa\":{ " + "             \"mailboxIds\": {\"" + mailboxId.serialize() + "\": true}" + "           }" + "         }" + "       }, " + "     \"c1\"" + "   ]" + " ]" + "}";
    IntStream.range(0, 19).forEach(i -> given().auth().basic(BOB.asString(), BOB_PASSWORD).contentType(ContentType.JSON).accept("application/json; jmapVersion=rfc-8621").body(requestBody).post("/jmap"));
    awaitSearchUpToDate();
    // THEN we expect CEDRIC to be reported with a 95% quota ration by quota search
