@Test
default void priorityShouldReorderMailsWhenDequeing() throws Exception {
    getMailQueue().enQueue(defaultMail().name("name3").attribute(mailPriority(3)).build());
    getMailQueue().enQueue(defaultMail().name("name9").attribute(mailPriority(9)).build());
    getMailQueue().enQueue(defaultMail().name("name1").attribute(mailPriority(1)).build());
    getMailQueue().enQueue(defaultMail().name("name8").attribute(mailPriority(8)).build());
    getMailQueue().enQueue(defaultMail().name("name6").attribute(mailPriority(6)).build());
    getMailQueue().enQueue(defaultMail().name("name0").attribute(mailPriority(0)).build());
    getMailQueue().enQueue(defaultMail().name("name7").attribute(mailPriority(7)).build());
    getMailQueue().enQueue(defaultMail().name("name4").attribute(mailPriority(4)).build());
    getMailQueue().enQueue(defaultMail().name("name2").attribute(mailPriority(2)).build());
    getMailQueue().enQueue(defaultMail().name("name5").attribute(mailPriority(5)).build());
    getMailQueue().enQueue(defaultMail().name("name-3").attribute(mailPriority(-3)).build());
    getMailQueue().enQueue(defaultMail().name("name-9").attribute(mailPriority(-9)).build());
    getMailQueue().enQueue(defaultMail().name("name-1").attribute(mailPriority(-1)).build());
    getMailQueue().enQueue(defaultMail().name("name-8").attribute(mailPriority(-8)).build());
    getMailQueue().enQueue(defaultMail().name("name-6").attribute(mailPriority(-6)).build());
    getMailQueue().enQueue(defaultMail().name("name-7").attribute(mailPriority(-7)).build());
    getMailQueue().enQueue(defaultMail().name("name-4").attribute(mailPriority(-4)).build());
    getMailQueue().enQueue(defaultMail().name("name-2").attribute(mailPriority(-2)).build());
    getMailQueue().enQueue(defaultMail().name("name-5").attribute(mailPriority(-5)).build());
    Iterable<MailQueue.MailQueueItem> items = Flux.from(getMailQueue().deQueue()).take(19).flatMap(item -> {
        try {
            item.done(MailQueue.MailQueueItem.CompletionStatus.SUCCESS);
            return Mono.just(item);
        } catch (MailQueue.MailQueueException e) {
            return Mono.error(e);
        }
    }).toIterable();
    assertThat(items).extracting(MailQueue.MailQueueItem::getMail).extracting(Mail::getName).containsExactly("name9", "name8", "name7", "name6", "name5", "name4", "name3", "name2", "name1", "name0", "name-3", "name-9", "name-1", "name-8", "name-6", "name-7", "name-4", "name-2", "name-5");
}

@Test
default void negativePriorityShouldDefaultToMinimumPriority() throws Exception {
    getMailQueue().enQueue(defaultMail().name("name0").attribute(mailPriority(-1)).build());
    getMailQueue().enQueue(defaultMail().name("name1").attribute(mailPriority(1)).build());
    Iterator<MailQueue.MailQueueItem> mailQueueItems = Flux.from(getMailQueue().deQueue()).subscribeOn(SCHEDULER).toIterable().iterator();
    MailQueue.MailQueueItem mailQueueItem1 = mailQueueItems.next();
    mailQueueItem1.done(MailQueue.MailQueueItem.CompletionStatus.SUCCESS);
    MailQueue.MailQueueItem mailQueueItem2 = mailQueueItems.next();
    mailQueueItem2.done(MailQueue.MailQueueItem.CompletionStatus.SUCCESS);
    assertThat(mailQueueItem1.getMail().getName()).isEqualTo("name1");
    assertThat(mailQueueItem2.getMail().getName()).isEqualTo("name0");
}

