@Test
void dequeueShouldNotRetryWhenBlobIsMissing(CassandraCluster cassandra) throws Exception {
    String name1 = "myMail1";
    String name2 = "myMail2";
    String name3 = "myMail3";
    getMailQueue().enQueue(defaultMail().name(name1).build());
    getMailQueue().enQueue(defaultMail().name(name2).build());
    getMailQueue().enQueue(defaultMail().name(name3).build());
    cassandra.getConf().registerScenario(returnEmpty().forever().whenQueryStartsWith("SELECT * FROM blobs WHERE id=:id"));
    ConcurrentLinkedDeque<String> dequeuedNames = new ConcurrentLinkedDeque<>();
    Flux.from(getMailQueue().deQueue()).take(3).doOnNext(item -> dequeuedNames.add(item.getMail().getName())).flatMap(item -> Mono.fromRunnable(Throwing.runnable(() -> item.done(MailQueue.MailQueueItem.CompletionStatus.SUCCESS))).subscribeOn(Schedulers.fromExecutor(EXECUTOR))).subscribeOn(Schedulers.fromExecutor(EXECUTOR)).subscribe();
    // One second should be enough to attempt dequeues while we fail to load blobs
    Thread.sleep(1000);
    // Restore normal behaviour
    cassandra.getConf().registerScenario(executeNormally().forever().whenQueryStartsWith("SELECT * FROM blobs WHERE id=:id"));
    // Let one second to check if the queue is empty
    Thread.sleep(1000);
    // We expect content missing blob references to be purged from the queue
    assertThat(dequeuedNames).isEmpty();
}

