@Test
void selectEnqueuedMailsShouldWork() throws Exception {
    testee.insert(EnqueuedItemWithSlicingContext.builder().enqueuedItem(EnqueuedItem.builder().enqueueId(ENQUEUE_ID).mailQueueName(OUT_GOING_1).mail(FakeMail.builder().name(NAME).build()).enqueuedTime(NOW).mimeMessagePartsId(MIME_MESSAGE_PARTS_ID).build()).slicingContext(EnqueuedItemWithSlicingContext.SlicingContext.of(BucketId.of(BUCKET_ID_VALUE), NOW)).build()).block();
    testee.insert(EnqueuedItemWithSlicingContext.builder().enqueuedItem(EnqueuedItem.builder().enqueueId(ENQUEUE_ID).mailQueueName(OUT_GOING_1).mail(FakeMail.builder().name(NAME).build()).enqueuedTime(NOW).mimeMessagePartsId(MIME_MESSAGE_PARTS_ID).build()).slicingContext(EnqueuedItemWithSlicingContext.SlicingContext.of(BucketId.of(BUCKET_ID_VALUE + 1), NOW)).build()).block();
    List<EnqueuedItemWithSlicingContext> selectedEnqueuedMails = testee.selectEnqueuedMails(OUT_GOING_1, SLICE_OF_NOW, BUCKET_ID).collectList().block();
    assertThat(selectedEnqueuedMails).hasSize(1).hasOnlyOneElementSatisfying(selectedEnqueuedMail -> {
        EnqueuedItem enqueuedItem = selectedEnqueuedMail.getEnqueuedItem();
        EnqueuedItemWithSlicingContext.SlicingContext slicingContext = selectedEnqueuedMail.getSlicingContext();
        assertSoftly(softly -> {
            softly.assertThat(slicingContext.getBucketId()).isEqualTo(BUCKET_ID);
            softly.assertThat(slicingContext.getTimeRangeStart()).isEqualTo(NOW.truncatedTo(ChronoUnit.MILLIS));
            softly.assertThat(enqueuedItem.getMailQueueName()).isEqualTo(OUT_GOING_1);
            softly.assertThat(enqueuedItem.getEnqueuedTime()).isEqualTo(NOW.truncatedTo(ChronoUnit.MILLIS));
            softly.assertThat(enqueuedItem.getEnqueueId()).isEqualTo(ENQUEUE_ID);
            softly.assertThat(enqueuedItem.getMail().getName()).isEqualTo(NAME);
            softly.assertThat(enqueuedItem.getPartsId()).isEqualTo(MIME_MESSAGE_PARTS_ID);
        });
    });
}

