    when(rspamdHttpClient.checkV2(any(Mail.class), eq(RspamdHttpClient.Options.forUser(Username.of("user1@exemple.com"))))).thenReturn(Mono.just(AnalysisResult.builder().action(AnalysisResult.Action.NO_ACTION).score(12.1F).requiredScore(14F).build()));
    when(rspamdHttpClient.checkV2(any(Mail.class), eq(RspamdHttpClient.Options.forUser(Username.of("user2@exemple.com"))))).thenReturn(Mono.just(AnalysisResult.builder().action(AnalysisResult.Action.REJECT).score(12.1F).requiredScore(14F).build()));
    mailet = new RspamdScanner(rspamdHttpClient, configuration);
    FakeMailContext mailetContext = FakeMailContext.defaultContext();
