    mailet = new RspamdScanner(rspamdHttpClient, configuration);
    FakeMailContext mailetContext = FakeMailContext.defaultContext();
    mailet.init(FakeMailetConfig.builder().setProperty("virusProcessor", "virus").setProperty("rejectSpamProcessor", "spam").mailetContext(mailetContext).build());
    Mail mail = FakeMail.builder().name("name").recipients("user1@exemple.com", "user2@exemple.com").mimeMessage(MimeMessageBuilder.mimeMessageBuilder().addToRecipient("user1@exemple.com").addFrom("sender@exemple.com").setSubject(INIT_SUBJECT).setText("Please!").build()).build();
    mailet.service(mail);
    assertThat(mail.getRecipients()).containsOnly(new MailAddress("user1@exemple.com"));
    assertThat(mailetContext.getSentMails().get(0).getState()).isEqualTo("virus");
    assertThat(mailetContext.getSentMails().get(0).getRecipients()).containsOnly(new MailAddress("user2@exemple.com"));
}

