@Test
void serviceShouldWriteSpamAttributeOnMail() throws Exception {
    FakeMailetConfig mailetConfiguration = FakeMailetConfig.builder().mailetName("SpamAssassin").build();
    SpamAssassin mailet = mailet();
    mailet.init(mailetConfiguration);
    Mail mail = FakeMail.builder().name("name").recipient("user1@exemple.com").mimeMessage(MimeMessageBuilder.mimeMessageBuilder().addToRecipient("user1@exemple.com").addFrom("sender@exemple.com").setSubject("testing").setText("Please!").build()).build();
    mailet.service(mail);
    assertThat(mail.getPerRecipientSpecificHeaders().getHeadersByRecipient().get(new MailAddress("user1@exemple.com")).stream().map(PerRecipientHeaders.Header::getName).collect(ImmutableList.toImmutableList())).contains(SpamAssassinResult.FLAG_MAIL.asString(), SpamAssassinResult.STATUS_MAIL.asString());
}

@Test
void serviceShouldWriteMessageAsNotSpamWhenNotSpam() throws Exception {
    FakeMailetConfig mailetConfiguration = FakeMailetConfig.builder().mailetName("SpamAssassin").build();
    SpamAssassin mailet = mailet();
    mailet.init(mailetConfiguration);
    Mail mail = FakeMail.builder().name("name").recipient("user1@exemple.com").mimeMessage(MimeMessageBuilder.mimeMessageBuilder().addToRecipient("user1@exemple.com").addFrom("sender@exemple.com").setSubject("testing").setText("Please!").build()).build();
    mailet.service(mail);
    assertThat(mail.getPerRecipientSpecificHeaders()).isEqualTo(new PerRecipientHeaders().addHeaderForRecipient(PerRecipientHeaders.Header.builder().name(SpamAssassinResult.FLAG_MAIL.asString()).value("NO"), new MailAddress("user1@exemple.com")).addHeaderForRecipient(PerRecipientHeaders.Header.builder().name(SpamAssassinResult.STATUS_MAIL.asString()).value("No, hits=3 required=5"), new MailAddress("user1@exemple.com")));
}

@Test
void serviceShouldWriteMessageAsSpamWhenSpam() throws Exception {
    FakeMailetConfig mailetConfiguration = FakeMailetConfig.builder().mailetName("SpamAssassin").build();
